inputs.common/ai_regional_objectives/00_ai_regi:
# Generic objectives
ai_regional_objective_acquire_states = {
	stances = { stance_conquer_region stance_colonize_region }

	possible = {
		scope:target_region = {
			any_scope_state = {
				aro_is_acquire_states_candidate = yes
			}
		}
	}

	on_create = {
		scope:target_region = {
			ordered_scope_state = {
				limit = {
					aro_is_acquire_states_candidate = yes
				}
				order_by = "root.military_reach(this)"
				max = 3
				check_range_bounds = no
				root = {
					add_to_variable_map = {
						name = aro_acquire_states_targets
						key = prev.state_region
						value = scope:target_region
					}
				}
			}
		}
	}

	complete = {
		scope:target_region = {
			any_scope_state = {
				owner = root
				aro_is_acquire_states_target = yes
			}
		}
	}

	invalid = {
		NOT = {
			scope:target_region = {
				any_scope_state = {
					NOT = { owner = root }
					aro_is_acquire_states_target = yes
				}
			}
		}
	}

	state_target = {
		scope:target_state = {
			NOT = { owner = root }
			aro_is_acquire_states_target = yes
		}
	}

	on_complete = {
		scope:target_region = {
			every_scope_state = {
				limit = {
					aro_is_acquire_states_target = yes
				}
				root = {
					remove_from_variable_map = {
						name = aro_acquire_states_targets
						key = prev.state_region
					}
				}
			}
		}
	}

	on_invalid = {
		scope:target_region = {
			every_scope_state = {
				limit = {
					aro_is_acquire_states_target = yes
				}
				root = {
					remove_from_variable_map = {
						name = aro_acquire_states_targets
						key = prev.state_region
					}
				}
			}
		}
	}

	weight = {
		value = 10

		if = {
			limit = { scope:target_stance = srs:stance_conquer_region }
			add = 10
		}
	}
}

