		if = { # Great Powers with significant navies should pay attention to Japan
			limit = {
				scope:region = {
					this = sr:region_northeast_asia
				}
			}
			if = {
				limit = {
					exists = c:JAP
					c:JAP ?= { has_law_or_variant = law_type:law_isolationism }
					country_rank = rank_value:great_power
					carrying_capacity >= 10
				}
				add = 1000
			}
		}
	}

	secret_goal_scores = {
		dominate = {
			score = {
				if = {
					limit = {
						NOT = { scope:target_country = { is_subject_of = root } }
						has_technology_researched = nationalism  # Just to make sure it doesn't happen immediately in 1836
						country_rank = rank_value:great_power
						can_reach_target_country_to_subjugate = { TARGET_COUNTRY = scope:target_country }
						scope:target_country = {
							country_has_primary_culture = cu:japanese
							has_law_or_variant = law_type:law_isolationism
							gdp >= 2000000
							capital.region = sr:region_northeast_asia
						}
					}
					add = 500
				}
				else_if = {
					limit = {
						NOT = { scope:target_country = { is_subject_of = root } }
						can_reach_target_country_to_subjugate = { TARGET_COUNTRY = scope:target_country }
						scope:target_country = {
							has_law_or_variant = law_type:law_isolationism
							gdp >= 2000000
							NOT = { country_has_primary_culture = cu:japanese }
						}
					}
					add = 100
				}

				if = {
					limit = {
						NOT = { scope:target_country = { is_subject_of = root } }
						has_strategic_adjacency = scope:target_country
						root.country_rank > scope:target_country.country_rank
						scope:target_country.country_rank < rank_value:major_power
						scope:target_country = {
							NOT = {
								has_law_or_variant = law_type:law_free_trade
							}
						}
					}
					add = 50

					if = {
						limit = {
							NOT = { scope:target_country = { is_subject_of = root } }
							scope:target_country = { is_country_type = unrecognized }
						}
						add = 50
					}
					else_if = {
						limit = {
							scope:target_country = { NOT = { is_country_type = unrecognized } }
						}
						add = -25
					}
				}
			}
		}
		conquer = {
			score = {
				if = {
					limit = {
						has_strategic_adjacency = scope:target_country
						scope:target_country = { is_country_type = unrecognized }
					}
					add = 50
				}
				else_if = {
					limit = {
						scope:target_country = { NOT = { is_country_type = unrecognized } }
					}
					add = -50
				}

				# Don't attack Japan outright, open them instead
				if = {
					limit = {
						scope:target_country = {
							country_has_primary_culture = cu:japanese
							has_law_or_variant = law_type:law_isolationism
							gdp >= 2000000
							capital.region = sr:region_northeast_asia
						}
					}
					add = -1000
				}
			}
		}
	}

	wargoal_weights = {
		make_subject = 1.5
		force_nationalization = 1.5
	}

	treaty_port_value = {
		if = {
			limit = {
				scope:target_country = {
					has_law_or_variant = law_type:law_isolationism
					gdp >= 2000000 # Not worth doing against very small markets
				}
				scope:target_state = { is_incorporated = yes }
				can_reach_target_state_to_coerce = { TARGET_STATE = scope:target_state }
			}
			add = {
				value = 50

				# More likely to grab a treaty port if we're already enemies in a play, ie they attacked us first
				if = {
					limit = { is_diplomatic_play_enemy_of = scope:target_country }
					multiply = 2.0
				}
			}
		}

		# Eager to reclaim a treaty port from a country that recently reneged on the agreement we inherited to them
		if = {
			limit = {
				has_variable = wants_treaty_port_revenge_against
				var:wants_treaty_port_revenge_against ?= scope:target_country
				can_reach_target_state_to_coerce = { TARGET_STATE = scope:target_state }
			}
			add = 100
		}
	}

	wargoal_scores = {
		# Need to have identical weights for foreign_investment_rights and open_market here as which one is used depends on whether Foreign Investment is available
		foreign_investment_rights = {
			value = 0

			if = {
				limit = {
					country_rank = rank_value:great_power
					can_reach_target_country_to_coerce = { TARGET_COUNTRY = scope:target_country }
					scope:target_country = {
						has_law_or_variant = law_type:law_isolationism
						gdp >= 5000000 # Not worth doing against small markets
					}
				}
				add = {
					value = 100

					# Less interested in foreign investment rights as a sway or defensive wargoal
					if = {
						limit = { is_diplomatic_play_involved_with = scope:target_country }
						multiply = 0.2
					}
					else_if = { # Very high score for opening Japan
						limit = {
							scope:target_country = {
								exists = c:JAP
								c:JAP ?= THIS
								has_law_or_variant = law_type:law_isolationism
							}
						}
						multiply = 10
					}
				}
			}
		}
		open_market = {
			value = 0

			if = {
				limit = {
					country_rank = rank_value:great_power
					can_reach_target_country_to_coerce = { TARGET_COUNTRY = scope:target_country }
					scope:target_country = {
						has_law_or_variant = law_type:law_isolationism
						gdp >= 5000000 # Not worth doing against small markets
					}
				}
				add = {
					value = 100

					# Less interested in open market as a sway or defensive wargoal
					if = {
						limit = { is_diplomatic_play_involved_with = scope:target_country }
						multiply = 0.2
					}
					else_if = { # Very high score for opening Japan
						limit = {
							scope:target_country = {
								exists = c:JAP
								c:JAP ?= THIS
								has_law_or_variant = law_type:law_isolationism
							}
						}
						multiply = 10
					}
				}
			}
		}
	}

	subject_value = {
		if = { # A sizeable state outside our market is worth bringing inside it
			limit = {
				NOT = { is_in_customs_union_with = scope:target_country }
				scope:target_country = {
					is_subject = no
					gdp >= 2000000
				}
			}
			add = 25
		}
	}

	treaty_category_scores = {
		trade = {
			value = 5
		}

		economy = {
			value = 4
		}

		expansion = {
			value = -2
		}
	}

	possible = {
		is_subject = no
		navy_size >= 25
		is_country_type = recognized
		NOT = { has_law_or_variant = law_type:law_isolationism }
		OR = {
			country_rank = rank_value:major_power
			country_rank = rank_value:great_power
		}
	}

	weight = {
		value = 10

		if = {
			limit = { country_rank = rank_value:great_power }
			add = 10
		}

		if = {
			limit = {
				exists = c:FRA
				c:FRA = this
				ruler = {
					OR = {
						var:dynasty_var ?= flag:house_bonaparte
						var:dynasty_var ?= flag:house_orleans
					}
				}
			}
			add = 10
		}

		# AI implications for Power Blocs: 'Economic Imperialism' strategy is more likely for Blocs with Market Unification
		if = {
			limit = {
				power_bloc ?= {
					has_principle_group = principle_group:principle_group_market_unification
				}
			}
			add = 5
		}

		if = {
			limit = {
				exists = c:JAP
				has_strategic_adjacency = c:JAP
				c:JAP ?= { has_law_or_variant = law_type:law_isolationism }
			}
			multiply = 2.0
		}

		if = {
			limit = { navy_size < 50 }
			multiply = 0.5
		}

		if = {
			limit = { navy_size >= 75 }
			multiply = 1.5
		}

		if = {
			limit = { has_radical_leftist_government = yes }
			multiply = {
				value = 1
				subtract = {
					value = 1
					subtract = 0.25
					multiply = {
						value = 1
						add = modifier:country_other_country_socialist_government_hostility_impact_mult
					}
				}
				min = 0
			}
		}
	}
}

