						ig_approval <= -10
					}
				}
				multiply = 1.5
			}

			if = { # If we are Conservative dont immediately hang any Liberal politician and so on
				limit = {
					scope:actor ?= {
						has_strategy = ai_strategy_conservative_agenda
					}
					has_liberal_ideology = yes
				}
				multiply = 0.5
			}
			else_if = {
				limit = {
					scope:actor ?= {
						has_strategy = ai_strategy_progressive_agenda
					}
					OR = {
						has_liberal_ideology = yes
						has_progressive_ideology = yes
					}
				}
				multiply = 0.5
			}
			else_if = {
				limit = {
					scope:actor ?= {
						has_strategy = ai_strategy_egalitarian_agenda
						NOT = { has_law_or_variant = law_type:law_council_republic }
					}
					OR = {
						has_liberal_ideology = yes
						has_progressive_ideology = yes
						has_socialist_ideology = yes
					}
				}
				multiply = 0.5
			}
			else_if = {
				limit = {
					scope:actor ?= {
						has_strategy = ai_strategy_egalitarian_agenda
					}
					OR = {
						has_progressive_ideology = yes
						has_socialist_ideology = yes
					}
				}
				multiply = 0.5
			}

			if = { # Be less inclined to toss out politicians
				limit = {
					NOT = { has_role_of_type = agitator }
				}
				multiply = 0.25
			}
		}

		if = {
			limit = {
				owner ?= {
					has_journal_entry = je_tp_tsar_unshakable_autocracy
					NOT = { has_variable = je_tp_tsar_unshakable_autocracy_button_1_complete }
				}
				has_role_of_type = agitator
				OR = {
					has_socialist_ideology = yes
					has_progressive_ideology = yes
					has_liberal_ideology = yes
				}
			}
			add = 20
		}
		if = {
			limit = {
				save_temporary_scope_as = tp_exile_candidate_scope
				owner ?= {
					has_journal_entry = je_tp_fav_bootlicker
					OR = {
						var:tp_bootlicker_rival_1 ?= scope:tp_exile_candidate_scope
						var:tp_bootlicker_rival_2 ?= scope:tp_exile_candidate_scope
						var:tp_bootlicker_rival_3 ?= scope:tp_exile_candidate_scope
					}
				}
			}
			add = 30
		}
		if = {
			limit = {
				owner ?= {
					has_journal_entry = je_tp_pool_decrease_landowner_influence
					ruler ?= {
						is_interest_group_type = ig_landowners
					}
				}
				is_interest_group_type = ig_landowners
				is_interest_group_leader = yes
				je_tsarpoints_landowner_ideology_close_enough = no
				interest_group ?= {
					any_scope_character = {
						has_role_of_type = politician
						is_interest_group_leader = no
						je_tsarpoints_landowner_ideology_close_enough = yes
					}
				}
			}
			add = 40
		}
		if = {
			limit = {
				owner ?= {
					has_journal_entry = je_tp_tsar_heir_of_alexander
					NOT = { has_variable = je_tp_tsar_heir_of_alexander_button_4_complete }
				}
				is_interest_group_type = ig_rural_folk
				is_interest_group_leader = yes
				OR = {
					has_liberal_ideology = yes
					has_progressive_ideology = yes
					has_socialist_ideology = yes
				}
			}
			add = 40
		}
		if = {
			limit = {
				has_template = RUS_grigoriy_rasputin
				has_role = character_role_favorite
			}
			multiply = 0
		}
		if = {
			limit = {
				has_template = RUS_alexander_pushkin
			}
			multiply = 0
		}
	}
}

