			trigger = {
				custom_tooltip = {
					text = "DIPLOMATIC_PACT_REQUIREMENT_NOT_DECENTRALIZED"
					NOT = { is_country_type = decentralized }
					scope:target_country = {
						NOT = { is_country_type = decentralized }
					}
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = DIPLO_ACTION_RELATIONS_AMICABLE_OR_GREATER_NOT
					NOT = {
						scope:target_country.relations:root >= relations_threshold:amicable
					}
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				NOT = { has_diplomats_expelled = scope:target_country }
			}
		}

		requirement_to_maintain = {
			trigger = {
				NOT = { scope:target_country = { has_diplomats_expelled = root } }
			}
		}
	}

	ai = {
		max_influence_spending_fraction = 0.25

		evaluation_chance = {
			value = 0.5
		}

		propose_score = {
			value = 5

			if = {
				limit = {
					OR = {
						ai_has_regional_objective_befriend_reason = { TARGET = scope:target_country }
						ai_is_regional_objective_protect_target = { TARGET = scope:target_country }
					}
				}

				add = 20
			}

			if = {
				limit = {
					has_attitude = {
						who = scope:target_country
						attitude = protective
					}
				}

				add = 5
			}

			if = {
				limit = {
					has_attitude = {
						who = scope:target_country
						attitude = conciliatory
					}
				}

				add = 20
			}

			if = {
				limit = {
					has_journal_entry = je_hawaiian_interest
					c:HAW ?= {
						this = scope:target_country
					}
				}
				add = 20
			}

			add = {
				value = scope:target_country.country_rank
				multiply = 3
			}

			if = {
				limit = {
					OR = {
						is_subject_of = scope:target_country
						scope:target_country = { is_subject_of = root }
					}
				}

				multiply = 2
			}
		}

		will_propose = {
			OR = {
				AND = {
					has_attitude = {
						who = scope:target_country
						attitude = cooperative
					}
					country_rank <= scope:target_country.country_rank
				}
				has_attitude = {
					who = scope:target_country
					attitude = conciliatory
				}
				has_attitude = {
					who = scope:target_country
					attitude = genial
				}
				has_attitude = {
					who = scope:target_country
					attitude = protective
				}
				ai_has_regional_objective_befriend_reason = { TARGET = scope:target_country }
				ai_is_regional_objective_protect_target = { TARGET = scope:target_country }
			}
		}

		will_break = {
			NOR = {
				ai_has_regional_objective_befriend_reason = { TARGET = scope:target_country }
				ai_is_regional_objective_protect_target = { TARGET = scope:target_country }
			}

			OR = {
				NOR = {
					has_attitude = {
						who = scope:target_country
						attitude = genial
					}
					has_attitude = {
						who = scope:target_country
						attitude = conciliatory
					}
					has_attitude = {
						who = scope:target_country
						attitude = cooperative
					}
					has_attitude = {
						who = scope:target_country
						attitude = protective
					}
				}
				AND = {
					scope:target_country.relations:root >= relations_threshold:amicable
					OR = {
						country_rank >= rank_value:minor_power
						NOT = {
							has_attitude = {
								who = scope:target_country
								attitude = genial
							}
						}
					}
				}
			}

