		cost = 0
		forced_duration = 12

		market_owner = second_country

		requirement_to_maintain = {
			trigger = {
				scope:target_country = {
					OR = {
						is_direct_subject_of = root
						power_bloc.power_bloc_leader ?= root
					}
				}
			}
		}

		actor_can_break = {
			always = yes
		}

