		if = {
			limit = {
				owner ?= {
					has_law_or_variant = law_type:law_council_republic
					has_law_or_variant = law_type:law_single_party_state
				}
				is_in_government = yes
			}
			add = 50
		}

		# Labour Association Laws
		if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_factory_councils
				}
			}
			add = 125
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_combination_acts
				}
			}
			add = 100
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					OR = {
						has_law_or_variant = law_type:law_guild_system
						has_law_or_variant = law_type:law_anti_strike_laws
					}
				}
			}
			add = 50
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_right_to_associate
				}
			}
			add = -25
		}
		else_if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_corporatized_unions
				}
			}
			add = -50
		}

		if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					active_law:lawgroup_labour_associations ?= {
						has_amendment = amendment_type:amendment_factory_councils
					}
				}
			}
			add = 75
		}
		# Communal Administration favours the Trade Unions
		if = {
			limit = {
				is_interest_group_type = ig_trade_unions
				owner ?= {
					has_law_or_variant = law_type:law_communal_administration
				}
			}
			add = 50
		}
		# Revolutionary Guard favours the Armed Forces
		if = {
			limit = {
				is_interest_group_type = ig_armed_forces
				owner ?= {
					has_law_or_variant = law_type:law_revolutionary_guard
				}
			}
			add = 50
		}

		# Variables
		if = {
			limit = {
				owner ?= { has_variable = election_vanguardist_support }
			}
			add = 50
		}
		if = {
			limit = {
				owner ?= { has_variable = communism_1_done }
			}
			add = 100
		}

		# Multiplied by percent of peasants
		if = {
			limit = {
				owner ?= {
					"owner.pop_type_percent_country(pop_type:peasants)" >= 0.25
				}
			}
			multiply = {
				value = 1
				add = "owner.pop_type_percent_country(pop_type:peasants)"
			}
		}
		else = {
			multiply = 0.5
		}

		# Multiplied by GDP per capita percentage
		if = {
			limit = {
				owner.gdp_per_capita_ranking >= 20 # TODO PRCAL-46014: change this out for the ratio of global average gdp per capita to gdp per capita
			}
			multiply = {
				value = 1
				add = {
					value = owner.gdp_per_capita_ranking # TODO PRCAL-46014: change this out for the ratio of global average gdp per capita to gdp per capita
					divide = 100
				}
			}
		}
		else = {
			multiply = 0.5
		}

		if = { #Armed Forces should not become communist too often outside CRs.
			limit = {
				owner ?= {
					NOT = {
						has_law_or_variant = law_type:law_council_republic
					}
				}
				is_interest_group_type = ig_armed_forces
			}
			multiply = 0.3
		}
		if = {
			limit = {
				OR = {
					has_variable = chose_communism
					has_variable = chose_anarchism
				}
			}
			multiply = 0.5
		}
		if = {
			limit = {
				OR = {
					has_variable = chose_conservatism
					has_variable = chose_fascism
					has_variable = chose_ethno_nationalism
				}
			}
			multiply = 0.1
		}
		multiply = {
			value = 1
			add = interest_group.modifier:interest_group_ideology_vanguardist_leader_chance_mult
			desc = "EVENTS_AND_OTHER_EFFECTS"
		}
	}
}

