inputs.common/journal_entries/00_strike_je.txt:
je_strike = {
	icon = "gfx/interface/icons/event_icons/event_protest.dds"

	group = je_group_crises

	activation_description = {
		always = yes
	}

	is_shown_when_inactive = {
		has_technology_researched = political_agitation
		has_technology_researched = human_rights
		NOT = { has_law_or_variant = law_type:law_council_republic }
		ig:ig_trade_unions ?= {
			ig_counts_as_marginal = no
			ig_clout >= 0.1
		}
		ig:ig_industrialists ?= {
			ig_counts_as_marginal = no
		}
	}

	possible = {
		ig:ig_trade_unions ?= {
			is_in_government = no
			ig_approval < 0
		}
		OR = {
			institution_investment_level = {
				institution = institution_workplace_safety
				value < 3
			}
			institution_investment_level = {
				institution = institution_social_security
				value < 3
			}
		}
		# we should probably simplfy this
		any_scope_state = {
			is_incorporated = yes
			OR = {
				radical_fraction = {
					value >= 0.2
					pop_type = laborers
				}
				radical_fraction = {
					value >= 0.2
					pop_type = machinists
				}
			}
			any_scope_pop = {
				OR = {
					is_pop_type = laborers
					is_pop_type = machinists
				}
				standard_of_living < 15
				pop_acceptance >= acceptance_status_4
				OR = {
					pop_employment_building_group = bg_manufacturing
					pop_employment_building_group = bg_mining
					pop_employment_building_group = bg_private_infrastructure
				}
			}
		}
	}

	immediate = {
		trigger_event = { id = strike.1 }
		set_variable = {
			name = strike_timer_var
			value = 0
		}
	}

	outcome = {
		header = je_standard_completion_header
		effect_header = je_standard_on_completion_header
		color = "gold_positive"
		conclusion_desc = je_standard_completion_conclusion_desc
		trigger = {
			strike_goal_complete_trigger = yes
		}
		effect = {
			custom_tooltip = je_end_strike_tt
			if = {
				limit = {
					has_variable = strike_negotiator
				}
				trigger_event = {
					id = strike.8 # strikers appeased
				}
			}
			else_if = {
				limit = {
					has_variable = strike_breaker
				}
				trigger_event = {
					id = strike.9 # strikers crushed
				}
			}
			je_strike_cleanup = yes
		}
	}

	outcome = {
		flags = { hidden invalid_outcome }
		conclusion_desc = je_standard_failure_conclusion_desc
		trigger = {
			has_law_or_variant = law_type:law_council_republic
		}
		effect = {
			custom_tooltip = {
				text = end_strike_tt
				strike_end_effect = yes
			}
			je_strike_cleanup = yes
		}
	}

	on_monthly_pulse = {
		effect = {
			change_variable = {
				name = strike_timer_var
				add = 1
			}
		}
		events = {
			strike.3
		}
		random_events = {
			10 = 0
			1 = strike.5
			1 = strike.6
			1 = strike.7
		}
	}

	current_value = {
		value = root.var:strike_timer_var
	}

	goal_add_value = {
		value = 60
	}

	progressbar = yes

	status_desc = {
		first_valid = {
			triggered_desc = {
				desc = je_general_strike_warning
				trigger = {
					scope:journal_entry = {
						is_goal_complete = no
					}
				}
			}
			triggered_desc = {
				desc = je_general_strike_active
				trigger = {
					scope:journal_entry = {
						is_goal_complete = yes
					}
				}
			}
		}
	}

	weight = 100

	should_be_pinned_by_default_uninvolved_or_context = yes
}

