	}

	timeout = 3650 # ten years

	outcome = {
		header = je_standard_completion_header
		effect_header = je_standard_on_completion_header
		color = "gold_positive"
		conclusion_desc = je_standard_completion_conclusion_desc
		trigger = {
			"ROOT.economic_dependence(top_overlord)" < 2
			trigger_if = {
				limit = {
					root.market = top_overlord.market
				}
				market = { market_production_share = { target = ROOT value > 0.5 } }
			}
