			limit = {
				NOT = { has_government_type = gov_colonial_administration_spa }
				has_modifier = modifier_reformed_captaincy_general
			}
			remove_modifier = modifier_reformed_captaincy_general
		}

		if = {
			limit = {
				country_has_voting_franchise = yes
				NOT = {
					modifier:country_electoral_confidence_over_time = 0
				}
				trigger_if = {
					limit = {
						modifier:country_electoral_confidence_over_time < 0
					}
					electoral_confidence > electoral_confidence_drift_limit # Can never drift to below 25%
				}
			}
			add_electoral_confidence = modifier:country_electoral_confidence_over_time
		}

		if = {
			limit = {
				country_has_voting_franchise = yes
			}
			if = {
				limit = {
					NOT = { has_variable = electoral_confidence_notified_band }
				}
				set_variable = {
					name = electoral_confidence_notified_band
					value = electoral_confidence_band
				}
			}
			else_if = {
				limit = {
					var:electoral_confidence_notified_band > electoral_confidence_band
				}
				save_scope_as = electoral_confidence_country
				post_notification = electoral_confidence_fell_notification
				clear_saved_scope = electoral_confidence_country
				set_variable = {
					name = electoral_confidence_notified_band
					value = electoral_confidence_band
				}
			}
			else_if = {
				limit = {
					var:electoral_confidence_notified_band < electoral_confidence_band
				}
				save_scope_as = electoral_confidence_country
				post_notification = electoral_confidence_rose_notification
				clear_saved_scope = electoral_confidence_country
				set_variable = {
					name = electoral_confidence_notified_band
					value = electoral_confidence_band
				}
			}
		}
		else_if = {
			limit = {
				has_variable = electoral_confidence_notified_band
			}
			remove_variable = electoral_confidence_notified_band
		}

		if = {
			limit = {
				is_player = yes
			}
			on_monthly_pulse_country_achievement_variable_effects = yes
		}

		if = {
			limit = {
				any_political_movement = {
					is_political_movement_type = movement_modernizer
				}
			}
			mutate_moderniser_movement_effect = yes # Relevant if owner has a moderniser movement
