			limit = {
				has_dlc_feature = ip4_content
				owner ?= {
					has_variable = manila_cathedral_count
					this.var:manila_cathedral_count >= 1
				}
				state = {
					state_region = s:STATE_LUZON
					has_building = building_manila_cathedral_ruins
					has_building = building_manila_cathedral_monument
				}
			}
			on_building_built_manila_cathedral_effect = yes
		}
		# Sagrada Família Cathedral - advance to the next construction stage
		if = {
			limit = {
				has_dlc_feature = ip4_content
				owner ?= {
					has_journal_entry = je_sagrada_familia
				}
				state = {
					state_region = s:STATE_CATALONIA
				}
			}
			if = { # Stage 1 Complete, Stage 2 Start
				limit = {
					state = { has_building = building_sagrada_familia_cathedral_1 }
				}
				owner ?= {
					trigger_event = { id = sagrada_familia.2 days = 3 }
				}
			}
			else_if = { # Stage 2 Complete, Stage 3 Start
				limit = {
					state = { has_building = building_sagrada_familia_cathedral_2 }
				}
				owner ?= {
					trigger_event = { id = sagrada_familia.3 days = 3 }
				}
			}
		}
		# Kaiserforum - advance to the next construction stage
		if = {
			limit = {
				has_dlc_feature = ip3_content
				owner ?= {
					has_journal_entry = je_kaiserforum
				}
				state = {
					state_region = s:STATE_AUSTRIA
				}
			}
			if = { # Stage 1 Complete, Stage 2 Start
				limit = {
					state = { has_building = building_kaiserforum_1 }
				}
				owner ?= {
					trigger_event = { id = kaiserforum.2 days = 3 }
				}
			}
			else_if = { # Stage 2 Complete, Stage 3 Start
				limit = {
					state = { has_building = building_kaiserforum_2 }
				}
				owner ?= {
					trigger_event = { id = kaiserforum.3 days = 3 }
				}
			}
		}
