# Root = journal entry
on_journal_entry_concluded = {
	effect = {
		if = {
			limit = {
				OR = {
					has_variable = tp_tsar_je_var
					has_variable = tp_favourite_je_var
				}
			}
			if = {
				limit = {
					has_variable = tp_je_war_completed_var # This has a particular way of working that can break scopes
				}
				post_notification = je_tp_war_mission_completed
			}
			else_if = {
				limit = {
					has_variable = tp_je_completed_var
				}
				post_notification = je_tp_mission_completed
			}
			else_if = {
				limit = {
					has_variable = tp_je_partial_completed_var
				}
				save_scope_as = je_tp_partial_mission_scope
				owner = {
					post_notification = je_tp_mission_partial_completed
				}
			}
			else_if = {
				limit = {
					has_variable = je_tp_fav_rasputin_fail_var
				}
				save_scope_as = je_tp_failed_mission_scope
				owner = {
					post_notification = je_tp_rasputin_mission_failed
				}
			}
			else = {
				save_scope_as = je_tp_failed_mission_scope
				owner = {
					if = {
						limit = {
							root ?= { has_variable = tp_favourite_je_var }
							OR = {
								NOT = { exists = root.var:je_fav_character_var }
								root.var:je_fav_character_var ?= { is_character_alive = no }
							}
						}
						post_notification = je_tp_mission_failed_favorite_died
					}
					else_if = {
						limit = {
							root ?= { has_variable = tp_favourite_je_var }
							root.var:je_fav_character_var ?= {
								is_character_alive = yes
								NOT = { has_role = character_role_favorite }
							}
						}
						post_notification = je_tp_mission_failed_favorite_dismissed
					}
					else_if = {
						limit = {
							exists = var:je_tsarpoints_tsar_var
							exists = root.var:je_tsarpoints_goal_fail_var
							NOT = {
								var:je_tsarpoints_tsar_var = root.var:je_tsarpoints_goal_fail_var
							}
						}
						post_notification = je_tp_mission_failed_new_ruler
					}
					else = {
						post_notification = je_tp_mission_failed
					}
				}
			}
			owner = {
				remove_variable = tp_last_mission_reward
			}
		}
		else = {
			post_notification = journal_entry_concluded
		}
	}
}

