			limit = {
				owner ?= { has_journal_entry = je_acw_countdown }
			}

			multiply = {
				value = 3.0
				desc = "je_acw_countdown"
			}
		}

		multiply = { # Illiterate pops participate at 1/10 the rate of fully literate pops
			desc = "POP_LITERACY"
			value = literacy_rate
			add = 0.10
		}
	}

