					NOR = {
						has_law_or_variant = law_type:law_slavery_banned
						has_law_or_variant = law_type:law_colonial_slavery
					}
				}
			}

			add = {
				owner = {
					every_scope_building = {
						limit = {
							is_building_type = building_barrack
							state = { is_slave_state = yes }
						}
						add = this.level
					}
				}

				divide = {
					value = owner.army_size
					min = 1
				}

				subtract = 0.5
				multiply = -1
				min = 0
				max = 0.5
				desc = "ARMY_FRACTION_IN_SLAVE_STATES"
			}
		}

		if = {
			limit = {
				owner.navy_size > 0
				owner = {
					NOR = {
						has_law_or_variant = law_type:law_slavery_banned
						has_law_or_variant = law_type:law_colonial_slavery
					}
				}
			}

			add = {
				owner = {
					every_scope_building = {
						limit = {
							is_building_type = building_naval_administration
							state = { is_slave_state = yes }
						}
						add = this.level
					}
				}

				divide = {
					value = owner.navy_size
					min = 1
				}

				subtract = 0.5
				multiply = -0.5
				min = 0
				max = 0.25
				desc = "NAVY_FRACTION_IN_SLAVE_STATES"
			}
		}

		add = movement_radicalism_acw_countdown

		if = {
			limit = {
				neighboring_country_has_insurrectionary_movement_trigger = { TYPE = movement_pro_slavery }
			}
			add = {
				desc = "NEIGHBOURING_COUNTRY_WITH_REVOLUTION"
				value = 0.15
			}
		}
		add = movement_radicalism_suppressed_after_civil_war
	}
}

