				trigger = {
					owner ?= { c:BIC ?= this }
				}
				weight = 1000
			}
		}
	}

	additional_radicalism_factors = {
		add = movement_radicalism_royalist_monarchy_abolished

		if = {
			limit = {
				neighboring_country_has_insurrectionary_movement_trigger = { TYPE = movement_royalist_constitutional }
			}
