				value = 5
			}
		}
		if = {
			limit = {
				scope:interest_group ?= {
					is_interest_group_type = ig_rural_folk
				}
			}
			multiply = {
				value = 2
			}
		}
	}

	pop_support_trigger = {
		NOR = {
			is_pop_type = aristocrats
			is_pop_type = slaves
		}
	}

	pop_support_factors = {
