		movement_support_high_literacy
		movement_support_below_expected_sol
		movement_support_farmers
		movement_support_laborers
		movement_support_peasants
	}

	pop_support_weight = {
		if = {
			limit = {
				exists = scope:political_movement
				scope:political_movement ?= {
						OR = {
							is_being_suppressed = yes
							is_being_bolstered = yes
						}
					}
				}
			if = {
				limit = {
					scope:political_movement = {
						is_being_suppressed = yes
					}
				}
				add = {
					value = suppression_base_value
					multiply = {
						value = -0.5
						add = owner.modifier:country_suppression_attraction_factor
					}
					desc = "concept_suppressed"
				}
			}
			else = {
				add = {
					value = bolstering_base_value
					multiply = {
						value = 0.5
						add = owner.modifier:country_bolster_attraction_factor
					}
					desc = "concept_bolstered"
				}
			}
		}

		if = {
			limit = {
				strata = middle
			}
			multiply = {
				value = 0.5
				desc = "MIDDLE_NO_ICON"
			}
			if = {
				limit = {
					is_pop_type = farmers
				}
				add = {
					value = 6
					desc = "POP_FARMERS"
				}
			}
		}
		else_if = {
			limit = {
				strata = lower
			}
			if = {
				limit = {
					is_pop_type = laborers
				}
				add = {
					value = 6
					desc = "POP_LABORERS"
				}
			}
			else_if = {
				limit = {
					is_pop_type = peasants
				}
				add = {
					value = 25
					desc = "POP_PEASANTS"
				}
			}
			else = {
				add = {
					value = 6
					desc = "LOWER_NO_ICON"
				}
			}
			if = {
				limit = {
					NOT = { is_pop_type = peasants } # Peasants already count this
					OR = {
						pop_employment_building_group = bg_agriculture
						pop_employment_building_group = bg_ranching
						pop_employment_building_group = bg_plantations
						pop_employment_building_group = bg_logging
						pop_employment_building_group = bg_fishing
						pop_employment_building_group = bg_whaling
						pop_employment_building_group = bg_manor_houses
					}
				}
				multiply = {
					value = 1.25
					desc = "RURAL_POP"
				}
			}
		}

		add = {
			desc = "URBAN_STATE" # Increases support in rural states, decreases in urban
			value = 0.5
			subtract = state.state_urbanization_rate
			multiply = 10
		}

		if = {
			limit = {
				standard_of_living < state.average_expected_sol
			}
			add = { # Increases likelihood of support if impoverished
				desc = "IS_BELOW_EXPECTED_SOL"
				value = state.average_expected_sol
				subtract = standard_of_living
				max = 10
			}
		}
		else_if = {
			limit = {
				standard_of_living > state.average_expected_sol
			}
			add = { # Decreases likelihood of support if well-off
				desc = "IS_ABOVE_EXPECTED_SOL"
				value = state.average_expected_sol
				subtract = standard_of_living
				min = -5
			}
		}

		multiply = { # Illiterate pops participate at 1/4 the rate of fully literate pops
			desc = "POP_LITERACY"
			value = literacy_rate
			add = 0.25
			max = 1.1 # Needs a less high literacy rate to get started, but caps out the same as other movements
		}

		multiply = { # Multiplied by 1.25x max
			desc = "POP_RADICALS"
			value = pop_radical_fraction
			divide = 4
			add = 1
		}
	}

	revolution = {
		possible = {
			political_movement_support >= 0.05
		}

		weight = {
			value = 100
		}

		state_weight = {
			value = 1
			add = scope:clout
			subtract = state_urbanization_rate
		}
	}

	secession = {
		possible = {
			political_movement_support >= 0.05
			OR = {
				scope:clout <= 0
				AND = {
					scope:clout > 0
					scope:clout < 0.15
					owner ?= {
						country_has_voting_franchise = no
						NOT = {
							any_interest_group = {
								is_in_government = yes
								law_stance = {
									law = law_type:law_peasant_proprietorship
									value > neutral
								}
							}
						}
					}
				}
			}
		}

		weight = {
			value = 1000
		}

		state_weight = {
			value = 1.5
			subtract = state_urbanization_rate
		}
	}

	additional_radicalism_factors = {
		if = {
			limit = {
				neighboring_country_has_insurrectionary_movement_trigger = { TYPE = movement_land_reform }
			}
			add = {
				desc = "NEIGHBOURING_COUNTRY_WITH_REVOLUTION"
				value = 0.15
			}
		}
		owner ?= {
			if = {
				limit = {
					has_journal_entry = je_russian_revolution
				}
				add = {
					desc = "russian_revolution_radicalism"
					value = 0.15
				}
			}
		}
		add = movement_radicalism_suppressed_after_civil_war
	}
}

