			desc = "LIBERTY_DESIRE_WEEKLY_CHANGE_NO_ARMY_POWER_PROJECTION_NEGATIVE"
		}
	}
	else_if = { #special case for BIC, DEI and RAJ, whose armies are huge compared to overlord, and who are basically the colonial powers influence in the region.
		limit = {
			root.second_country = {
