je_cuba_independencia_bar_target = {
	add = {
		add = 50
		desc = "base_value"
	}

	#Same slave law
	if = {
		limit = {
			AND = {
				c:CUB ?= {
					has_slavery = yes 
				}
				OR = {
					s:STATE_FLORIDA = {
						any_scope_state = {
							owner = {
								c:CSA ?= this
								has_slavery = yes 
							}
						}
					}
					AND = {
						s:STATE_FLORIDA = {
							NOT = {
								any_scope_state = {
									owner = {
										c:CSA ?= this
									}
								}
							}
						}
						c:USA ?= {
							has_slavery = yes 
						}
					}
				}
			}
		}
		add = {
			add = -15 
			desc = join_usa_same_slave_law_tt
		}
	}
	else_if = {
		limit = {
			AND = {
				c:CUB ?= {
					has_slavery = no 
				}
				OR = {
					s:STATE_FLORIDA = {
						any_scope_state = {
							owner = {
								c:CSA ?= this
								has_slavery = no 
							}
						}
					}
					AND = {
						s:STATE_FLORIDA = {
							NOT = {
								any_scope_state = {
									owner = {
										c:CSA ?= this
									}
								}
							}
						}
						c:USA ?= {
							has_slavery = no 
						}
					}
				}
			}
		}
		add = {
			add = -5 
			desc = join_usa_free_slave_law_tt
		}
	}
	else = {
		add = {
			add = 10
			desc = join_usa_different_slave_law_tt
		} 
	}


	#USA power bloc leverage. Note leverage advantage calculates backwards, so c:USA.power_bloc.leverage_advantage(c:CUB) returns a negative value as it checks cuba leverage vs USA. 
	if = {
		limit = {
			AND = {
				s:STATE_FLORIDA = {
					NOT = {
						any_scope_state = {
							owner = { c:CSA ?= this }
						}
					}
				}
				exists = c:USA.power_bloc
				exists = c:SPA.power_bloc
			}
		}
		add = {
			add = "c:USA.power_bloc.leverage_advantage(c:CUB)" 
			subtract = {
				add = "c:SPA.power_bloc.leverage_advantage(c:CUB)"
				divide = 2
			}
			multiply = -1
			multiply = je_cuba_join_usa_target_power_bloc_leverage_multiplier
			desc = join_usa_same_powerbloc_compared_to_spain_tt
			max = 0
			min = -25
		}
	}
	else_if = {
		limit = {
			AND = {
				s:STATE_FLORIDA = {
					any_scope_state = {
						owner = { c:CSA ?= this }
					}
				}
				exists = c:CSA.power_bloc
				exists = c:SPA.power_bloc
			}
		}
		add = {
			add = "c:CSA.power_bloc.leverage_advantage(c:CUB)" 
			subtract = {
				add = "c:SPA.power_bloc.leverage_advantage(c:CUB)"
				divide = 2
			}
			multiply = -1
			multiply = je_cuba_join_usa_target_power_bloc_leverage_multiplier
			desc = join_usa_same_powerbloc_compared_to_spain_tt
			max = 0
			min = -25
		}
	}
	else_if = {
		limit = {
			s:STATE_FLORIDA = {
				NOT = {
					any_scope_state = {
						owner = { c:CSA ?= this }
					}
				}
			}
			exists = c:USA.power_bloc
		}
		add = {
			add = "c:USA.power_bloc.leverage_advantage(c:CUB)" 
			multiply = je_cuba_join_usa_target_power_bloc_leverage_multiplier
			desc = join_usa_usa_powerbloc_tt
			multiply = -1
			max = 0
			min = -25 
		}
	}
	else_if = {
		limit = {
			exists = c:CSA.power_bloc
		}
		add = {
			add = "c:CSA.power_bloc.leverage_advantage(c:CUB)" 
			multiply = je_cuba_join_usa_target_power_bloc_leverage_multiplier
			desc = join_usa_usa_powerbloc_tt
			multiply = -1
			max = 0
			min = -25 
		}
	}
	else = {
		add = {
			add = 5
			desc = join_usa_no_powerblocs_tt
		}
	}

	#economic dependence
	if = {
		limit = {
			s:STATE_FLORIDA = {
				any_scope_state = {
					owner = { c:CSA ?= this }
				}
			}
		}
