		desc = "coup_popularity_vs_legitimacy_tt"
		every_scope_character = {
			limit = {
				has_variable = golpista_var
			}
			value = popularity
			divide = 10
		}
	}
	if = { # Land coups
		limit = {
			army_size_including_raised_conscripts > 0
			any_scope_character = {
				has_variable = golpista_var
				has_role_of_type = general
			}
		}
		add = {
			desc = "coup_commander_rank_progress_tt"
			every_scope_character = {
				limit = {
					has_variable = golpista_var
					has_role_of_type = general
				}
				value = this.commander_rank
				divide = owner.country_collected_army_commander_ranks
				multiply = 5
			}
		}
	}
	if = { # Boat coups
		limit = {
			navy_size > 0
			any_scope_character = {
				has_variable = golpista_var
				has_role_of_type = admiral
			}
		}
		add = {
			desc = "coup_commander_rank_progress_tt"
			every_scope_character = {
				limit = {
					has_variable = golpista_var
					has_role_of_type = admiral
				}
				value = this.commander_rank
				divide = owner.country_collected_navy_commander_ranks
				multiply = 5
			}
		}
	}
	if = {
		limit = {
			any_scope_character = {
				has_variable = golpista_var
				exists = this.commander_military_formation.current_hq
				this.commander_military_formation.current_hq.region ?= owner.capital.region
			}
		}
		add = {
			desc = "coup_commander_core_location_progress_tt"
			value = 2
		}
	}
	else_if = {
		limit = {
			any_scope_character = {
				has_variable = golpista_var
				exists = this.commander_military_formation.current_hq
				this.commander_military_formation.current_hq.region ?= {
					any_scope_state = {
						owner = root.owner
						is_incorporated = yes
					}
				}
			}
		}
		add = {
			desc = "coup_commander_periphery_location_progress_tt"
			value = 1
		}
	}
	else_if = {
		limit = {
			any_scope_character = {
				has_variable = golpista_var
				exists = this.commander_military_formation.current_hq
				this.commander_military_formation.current_hq.region ?= {
					any_scope_state = {
						owner = root.owner
						is_incorporated = no
					}
				}
			}
		}
		add = {
			desc = "coup_commander_colony_location_progress_tt"
			value = -2
		}
	}
	else_if = {
		limit = {
			any_scope_character = {
				has_variable = golpista_var
				exists = this.commander_military_formation
				NOT = {
					exists = this.commander_military_formation.current_hq
				}
			}
		}
		add = {
			desc = "coup_commander_no_location_progress_tt"
			value = -1
		}
	}
	else_if = {
		limit = {
			any_scope_character = {
				has_variable = golpista_var
				NOT = {
					exists = this.commander_military_formation
				}
			}
		}
		add = {
			desc = "coup_commander_unassigned_location_progress_tt"
			value = 2
		}
	}
	add = {
		desc = "coup_clout_of_golpista_ig_tt"
		every_interest_group = {
			limit = {
				has_variable = golpista_ig_var
			}
			value = ig_clout
			multiply = 10
		}
	}
	add = {
		desc = "coup_strength_modifier_add_tt"
		every_scope_character = {
			limit = {
				has_variable = golpista_var
			}
			value = 1
			add = modifier:character_coup_strength_add
		}
	}
	multiply = {
		desc = "coup_strength_modifier_tt"
		every_scope_character = {
			limit = {
				has_variable = golpista_var
			}
			value = 1
			add = modifier:character_coup_strength_mult
		}
	}
}

country_collected_army_commander_ranks = {
	if = {
		limit = {
			any_scope_character = {
				has_role_of_type = general
			}
		}
		value = 0
		every_scope_character = {
			limit = {
				has_role_of_type = general
				exists = commander_rank
			}
			add = this.commander_rank
		}
	}
	else = {
		value = 0
	}
}

country_collected_navy_commander_ranks = {
	if = {
		limit = {
			any_scope_character = {
				has_role_of_type = admiral
			}
		}
		value = 0
		every_scope_character = {
			limit = {
				has_role_of_type = admiral
				exists = commander_rank
			}
			add = this.commander_rank
		}
	}
	else = {
		value = 0
	}
}

country_coup_resistance = {
	add = {
		desc = "coup_legitimacy_tt"
		value = legitimacy
		divide = 10
	}
	add = {
		desc = "coup_resistance_modifier_add_tt"
		value = 1
		add = modifier:country_coup_resistance_add
	}
	multiply = {
		desc = "coup_resistance_modifier_tt"
		value = 1
		add = modifier:country_coup_resistance_mult
	}
}

country_coup_resistance_reversed = { # Must exactly match country_coup_resistance but reversed. I don't like that this has to exist either.
	subtract = {
		desc = "coup_legitimacy_tt"
		value = legitimacy
		divide = 10
	}
	subtract = {
		desc = "coup_resistance_modifier_add_tt"
		value = 1
		add = modifier:country_coup_resistance_add
	}
	multiply = {
		desc = "coup_resistance_modifier_tt"
		value = 1
		add = modifier:country_coup_resistance_mult
	}
}

inputs.common/script_values/ip5_je_values.txt:
##################
# General values #
##################

# Ceiling on a country's Innovation, scaling with literacy. Read by the Tsarpoints JE, its buttons and its scripted effects.
max_innovation = {
	value = 150
	multiply = literacy_rate
	add = 50
}

# The literacy rate a country is expected to have reached by the current year, ramping from 20% in 1836. Tsarpoints uses it to judge whether literacy is on track.
expected_literacy_rate_year = {
	value = year
	subtract = 1836
	multiply = 0.01
	min = 0.20
	max = 1
}

# Plain GDP per capita, guarded against division by zero on countries with no population.
# Base for five_year_plan_gdp_per_capita_value and read directly by 00_communism.txt.
country_gdp_per_capita = {
	value = gdp
	if = {
		limit = {
			total_population > 0
		}
		divide = total_population
	}
	else = {
		divide = 1
	}
}

#######################################################
# Socialism strength - shared by both journal entries #
#######################################################

# Country. How socialist a country is overall: 3x socialist movement support (saturating near 33% support) plus 2x socialist party clout (saturating near 50% clout).
# The root input of the whole RoR weighting system - feeds normalized_socialism_coefficient, the je_reform_or_revolution map colour, and the Council Republic Confrontation drift factor.
socialism_coefficient = {
	value = 0
	if = { # Max - 33% support
		limit = {
			any_political_movement = {
				is_political_movement_type = movement_socialist
			}
		}
		add = {
			desc = "socialism_coefficient_movement_support"
			every_political_movement = {
				limit = {
					is_political_movement_type = movement_socialist
				}
				value = {
					value = this.political_movement_support
					multiply = 3
				}
			}
		}
	}
	if = { # Max - 50% clout
		limit = {
			any_active_party = {
				party_counts_as_socialist_party = yes
				party_has_members = yes
			}
		}
		add = {
			desc = "socialism_coefficient_party_clout"
			every_active_party = {
				limit = {
					party_counts_as_socialist_party = yes
					party_has_members = yes
				}
				every_member = {
					add = this.ig_clout
				}
			}
			multiply = 2
		}
	}
}

# Party. Total clout of every interest group that is a member of this party.
# Read by the reform_or_revolution.1 event options and by loc; not part of the drift maths.
party_total_clout = { # Party
	value = 0
	every_member = {
		add = this.ig_clout
	}
}

# Country. This country's socialism_coefficient relative to the average across involved countries, centred on 1.
# Above 1 = more socialist than the involved average, below 1 = less. Reads the average_socialism_coefficient variable cached on the JE.
normalized_socialism_coefficient = {
	value = 1
	add = {
		value = this.socialism_coefficient
		subtract = je:je_reform_or_revolution.var:average_socialism_coefficient
	}
}

# Squared so that countries far from the average dominate the sum rather than merely leading it.
# This is the term that makes involved_country_percentage_of_total_involved_population_modified socialism-weighted.
normalized_socialism_coefficient_squared = {
	value = normalized_socialism_coefficient
	multiply = normalized_socialism_coefficient
}

################################################################
# Reform or Revolution - involved country population weighting #
################################################################

# JE. Count of countries involved in je_reform_or_revolution.
# Cached monthly into the num_involved_countries_var JE variable, which everything else reads instead of recomputing this.
num_involved_countries = {
	value = 0
	every_scope_je_involved = {
		add = 1
	}
}

# JE. Summed incorporated population of every involved country - the denominator for all population weighting.
# Cached monthly into the total_incorporated_population_of_involved_countries_var JE variable.
total_incorporated_population_of_involved_countries = {
	value = 0
	if = {
		limit = {
			var:num_involved_countries_var > 0
		}
		every_scope_je_involved = {
			add = cached_ai_incorporated_population
		}
	}
}

# Country. What fraction of this country's own population is incorporated.
# Used by the per-country map contribution to scale factors that only apply to incorporated pops.
percent_incorporated_population = { # country scope
	value = cached_ai_incorporated_population
	divide = total_population
}

# Country. This country's share of the total involved population. The plain population weight.
# Used by the coverage-style drift factors (institutions, factory councils), which are not socialism-weighted.
involved_country_percentage_of_total_involved_population = {
	if = {
		limit = {
			je:je_reform_or_revolution.var:total_incorporated_population_of_involved_countries_var > 0
		}
		value = total_population
		divide = je:je_reform_or_revolution.var:total_incorporated_population_of_involved_countries_var
	}
}

# Country. The same population share, multiplied by normalized_socialism_coefficient_squared.
# The socialism-weighted population weight, used by the political drift factors (parties in government, movements, trade union stances, Council Republic Confrontation, scripted bonuses).
involved_country_percentage_of_total_involved_population_modified = {
	value = involved_country_percentage_of_total_involved_population
	multiply = normalized_socialism_coefficient_squared
}

##############################################
# Reform or Revolution - drift factor inputs #
##############################################

# JE. Fraction of the involved population living under a Workplace Safety institution.
# Becomes reform_or_revolution_workplace_safety_var directly, the same way percent_of_population_under_factory_councils does; also shown as the percentage in the bar tooltip.
journal_entry_workplace_safety_institution_coverage = {
	every_scope_je_involved = {
		limit = {
			NOT = { has_factory_councils_law_or_amendment = yes }
			has_institution = institution_workplace_safety
		}
		add = cached_ai_incorporated_population
	}
	divide = var:total_incorporated_population_of_involved_countries_var
}

# JE. Fraction of the involved population living under a qualifying Social Security institution.
# Becomes reform_or_revolution_social_security_var directly.
journal_entry_social_security_institution_coverage = {
	every_scope_je_involved = {
		limit = {
			NOR = {
				has_factory_councils_law_or_amendment = yes
				has_law_or_variant = law_type:law_poor_laws
			}
			has_institution = institution_social_security
		}
		add = cached_ai_incorporated_population
	}
	divide = var:total_incorporated_population_of_involved_countries_var
}

# JE. Fraction of the involved population living under a qualifying Health System institution.
# Becomes reform_or_revolution_health_var directly.
journal_entry_public_health_institution_coverage = {
	every_scope_je_involved = {
		limit = {
			NOT = { has_factory_councils_law_or_amendment = yes }
			has_institution = institution_health_system
			has_law_or_variant = law_type:law_public_health_insurance
		}
		add = cached_ai_incorporated_population
	}
	divide = var:total_incorporated_population_of_involved_countries_var
}

# JE. Fraction of the involved population living under Factory Councils.
# Scaled by 10 into reform_or_revolution_factory_councils_var - the single largest Revolutionary drift factor.
# The institution coverage values above are the same calculation with a different limit, but are used unscaled.
percent_of_population_under_factory_councils = {
	every_scope_je_involved = {
		limit = {
			has_factory_councils_law_or_amendment = yes
		}
		add = cached_ai_incorporated_population
	}
	divide = var:total_incorporated_population_of_involved_countries_var
}

################################################
# Reform or Revolution - output and thresholds #
################################################

# Country. One country's net push on the RoR bar: positive is Revolutionary, negative is Reformist.
# Every factor here mirrors a reform_or_revolution_*_var block in journal_entry_update_reform_or_revolution_noninit_variables - keep the two in step when adding a factor.
# Cached per country into reform_or_revolution_contribution_cache, which drives the map mode tooltip, the communist Pop Attraction modifier and the reform_or_revolution event options.
reform_or_revolution_map_country_contribution_value = { # country scope
	if = {
		limit = {
			NOT = { has_factory_councils_law_or_amendment = yes }
			any_interest_group = {
				is_in_government = yes
				party ?= {
					is_party_type = socialist_party
				}
			}
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_SOCIALIST_PARTIES_IN_GOVERNMENT_TT"
			add = {
				value = -10
				multiply = involved_country_percentage_of_total_involved_population_modified
			}
		}
	}
	if = {
		limit = {
			has_law_or_variant = law_type:law_council_republic
			has_journal_entry = je_state_and_revolution
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_COUNCIL_REPUBLIC_CONFRONTATION_TT"
			add = {
				value = state_and_revolution_average_confrontation # 0-100
				multiply = {
					value = 0.1
					multiply = involved_country_percentage_of_total_involved_population_modified
				}
			}
		}
	}
	if = {
		limit = {
			any_political_movement = {
				OR = {
					is_political_movement_type = movement_socialist
					is_political_movement_type = movement_labor
				}
			}
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_INSURRECTIONARY_LABOR_OR_SOCIALIST_MOVEMENTS_TT"
			if = {
				limit = {
					any_political_movement = {
						OR = {
							is_political_movement_type = movement_socialist
							is_political_movement_type = movement_labor
						}
						is_insurrectionary = yes
					}
				}
				add = {
					value = 10
					multiply = involved_country_percentage_of_total_involved_population_modified
				}
			}
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_ACTIVISM_OF_LABOR_OR_SOCIALIST_MOVEMENTS_TT"
			if = {
				limit = {
					NOT = {
						has_law_or_variant = law_type:law_council_republic
					}
					any_political_movement = {
						OR = {
							is_political_movement_type = movement_socialist
							is_political_movement_type = movement_labor
						}
						this.political_movement_support >= 0.05
					}
				}
				every_political_movement = {
					limit = {
						OR = {
							is_political_movement_type = movement_socialist
							is_political_movement_type = movement_labor
						}
						this.political_movement_support >= 0.05
					}
					add = {
						value = -0.25
						add = this.political_movement_radicalism
						multiply = 10
					}
				}
				multiply = involved_country_percentage_of_total_involved_population_modified
			}
		}
	}
	if = {
		limit = {
			has_factory_councils_law_or_amendment = yes
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_FACTORY_COUNCILS_TT"
			add = {
				value = percent_incorporated_population
				multiply = involved_country_percentage_of_total_involved_population
			}
			multiply = 10
		}
	}
	if = {
		limit = {
			NOT = { has_factory_councils_law_or_amendment = yes }
			has_institution = institution_workplace_safety
		}
		subtract = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_WORKPLACE_SAFETY_TT"
			add = {
				value = percent_incorporated_population
				multiply = involved_country_percentage_of_total_involved_population
			}
		}
	}
	if = {
		limit = {
			NOR = {
				has_factory_councils_law_or_amendment = yes
				has_law_or_variant = law_type:law_poor_laws
			}
			has_institution = institution_social_security
		}
		subtract = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_SOCIAL_SECURITY_TT"
			add = {
				value = percent_incorporated_population
				multiply = involved_country_percentage_of_total_involved_population
			}
		}
	}
	if = {
		limit = {
			NOT = { has_factory_councils_law_or_amendment = yes }
			has_law = law_type:law_public_health_insurance
			has_institution = institution_health_system
		}
		subtract = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_HEALTH_TT"
			add = {
				value = percent_incorporated_population
				multiply = involved_country_percentage_of_total_involved_population
			}
		}
	}
	if = {
		limit = {
			ig:ig_trade_unions ?= {
				law_stance = {
					law = law_type:law_factory_councils
					value > neutral
				}
			}
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_TRADE_UNIONS_FACTORY_COUNCIL_STANCE_PRO_TT"
			add = {
				value = ig:ig_trade_unions.ig_clout
				multiply = {
					value = 10
					multiply = involved_country_percentage_of_total_involved_population_modified
				}
			}
		}
	}
	if = {
		limit = {
			ig:ig_trade_unions ?= {
				law_stance = {
					law = law_type:law_factory_councils
					value < neutral
				}
			}
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_TRADE_UNIONS_FACTORY_COUNCIL_STANCE_ANTI_TT"
			subtract = {
				value = ig:ig_trade_unions.ig_clout
				multiply = {
					value = 10
					multiply = involved_country_percentage_of_total_involved_population_modified
				}
			}
		}
	}
	if = {
		limit = {
			OR = {
				this.modifier:country_reform_or_revolution_revolution_bonus_add != 0
				this.modifier:country_reform_or_revolution_reform_bonus_add != 0
			}
		}
		add = {
			desc = "REFORM_OR_REVOLUTION_COUNTRY_BONUS_VALUES_TT"
			if = {
				limit = {
					this.modifier:country_reform_or_revolution_revolution_bonus_add != 0
				}
				add = {
					value = this.modifier:country_reform_or_revolution_revolution_bonus_add
					multiply = involved_country_percentage_of_total_involved_population_modified
				}
			}
			if = {
				limit = {
					this.modifier:country_reform_or_revolution_reform_bonus_add != 0
				}
				subtract = {
					value = this.modifier:country_reform_or_revolution_reform_bonus_add
					multiply = involved_country_percentage_of_total_involved_population_modified
				}
			}
		}
	}
}

# Fraction of involved countries that must be at war with each other before the RoR bar starts rushing towards its leading outcome (a 25x multiplier on the bar).
reform_or_revolution_war_threshold = 0.50

# Summed GDP of the countries on the socialist_movement_country_list global list.
# The monthly on_action activates je_reform_or_revolution once this passes 25% of global GDP.
reform_or_revolution_countries_gdp = {
	value = 0
	every_in_global_list = {
		variable = socialist_movement_country_list
		add = this.gdp
	}
}

# Movement support needed for Factory Councils to auto-activate as an amendment during a labour revolution. Referenced by loc only.
factory_council_activation_threshold = 0.75

#################################################
# State and Revolution - revolutionary bloc GDP #
#################################################

# The share of global GDP the revolutionary bloc is aiming for. The base constant behind every bloc GDP value below.
state_and_revolution_bloc_gdp_target = 0.50

# Half the bloc target - the market GDP share required for the Socialist World Republic check in 00_communism.txt.
state_and_revolution_swr_gdp_target = {
	value = state_and_revolution_bloc_gdp_target
	divide = 2
}

# Summed GDP of every country holding all three revolutionary laws.
revolutionary_bloc_gdp = {
	every_country = {
		limit = {
			has_all_revolutionary_laws = yes
		}
		add = gdp
	}
}

# The absolute GDP figure the bloc is aiming for, i.e. global GDP x the bloc target. Display value for the JE.
revolutionary_bloc_gdp_target = {
	value = global_gdp
	multiply = state_and_revolution_bloc_gdp_target
}

# The bloc's actual share of global GDP, clamped to 0-1.
# Doubled into both Confrontation pivots - a large revolutionary bloc makes every Council Republic bolder.
revolutionary_bloc_gdp_fraction = {
	value = revolutionary_bloc_gdp
	divide = {
		value = global_gdp
		min = 1
	}
	min = 0
	max = 1
}

############################################
# State and Revolution - pivot ingredients #
############################################

# Country. Total lower strata pop size, floored at 1 so it is safe as a denominator.
state_and_revolution_lower_strata_population = {
	every_scope_pop = {
		limit = {
			strata = lower
		}
		add = total_size
	}
	min = 1
}

# Country. Fraction of lower strata pops living below their expected standard of living.
# Cached into state_and_revolution_lower_strata_below_expected_sol_var and read by the Economic Consolidation pivot.
state_and_revolution_lower_strata_below_expected_sol_fraction = {
	every_scope_pop = {
		limit = {
			strata = lower
			standard_of_living < state.average_expected_sol
		}
		add = total_size
	}
	divide = state_and_revolution_lower_strata_population
}

# Country. Summed loyalist fraction across lower strata pops.
state_and_revolution_lower_strata_loyalists = {
	every_scope_pop = {
		limit = {
			strata = lower
		}
		add = pop_loyalist_fraction
	}
}

# Country. Count of lower strata pops, starting at 1 so it is safe as a denominator.
state_and_revolution_lower_strata_pops = {
	value = 1
	every_scope_pop = {
		limit = {
			strata = lower
		}
		add = 1
	}
}

# Country. Average loyalist fraction among lower strata pops.
# Cached into state_and_revolution_lower_strata_loyalist_fraction_var and read by the Political Confrontation pivot.
state_and_revolution_lower_strata_loyalist_fraction = {
	value = state_and_revolution_lower_strata_loyalists
	divide = state_and_revolution_lower_strata_pops
}

# Country. How far average standard of living exceeds expectations, scaled to 0-1 over 10 points of surplus.
# Economic Confrontation pivot - a comfortable population is willing to export the revolution.
state_and_revolution_sol_surplus = {
	value = average_sol
	subtract = average_expected_sol
	divide = 10
	min = 0
	max = 1
}

# Country. Fraction of the population that is still peasants.
# Economic Consolidation pivot; also the base of five_year_plan_peasant_fraction_value.
state_and_revolution_peasant_fraction = {
	every_scope_pop = {
		limit = {
			is_pop_type = peasants
		}
		add = total_size
	}
	divide = {
		value = total_population
		min = 1
	}
}

# Country. Grows as GDP per capita ranking worsens past 10th. Economic Consolidation pivot.
state_and_revolution_poor_gdp_per_capita_bonus = {
	if = {
		limit = {
			gdp_per_capita_ranking > 20
		}
		add = {
			value = gdp_per_capita_ranking
			multiply = 0.01
		}
	}
	min = 0
	max = 1
}

# Country. Count of owned states currently in famine. Quarter-weighted into the Economic Consolidation pivot.
state_and_revolution_famine_states = {
	every_scope_state = {
		limit = {
			has_famine = yes
		}
		add = 1
	}
}

# Country. How many of the three revolutionary laws are absent. Political Consolidation pivot.
state_and_revolution_missing_revolutionary_laws = {
	if = {
		limit = {
			NOT = { has_law_or_variant = law_type:law_revolutionary_guard }
		}
		add = 1
	}
	if = {
		limit = {
			NOT = { has_law_or_variant = law_type:law_communal_administration }
		}
		add = 1
	}
	if = {
		limit = {
			NOT = { has_law_or_variant = law_type:law_factory_councils }
		}
		add = 1
	}
}

# Country. How many of the three revolutionary laws are active. Political Confrontation pivot.
state_and_revolution_active_revolutionary_laws = {
	if = {
		limit = {
			has_law_or_variant = law_type:law_revolutionary_guard
		}
		add = 1
	}
	if = {
		limit = {
			has_law_or_variant = law_type:law_communal_administration
		}
		add = 1
	}
	if = {
		limit = {
			has_law_or_variant = law_type:law_factory_councils
		}
		add = 1
	}
}

# Country. Flat bonus for having won je_reform_or_revolution on the Revolutionary side. Feeds both Confrontation pivots.
state_and_revolution_revolutionary_victory_bonus = {
	if = {
		limit = {
			had_revolutionary_socialism_victory = yes
		}
		add = 0.25
	}
}

# Country. Grows with each land-adjacent country undergoing a socialist, communist or anarchist revolution. Feeds both Confrontation pivots.
state_and_revolution_neighbour_communist_revolution_bonus = {
	every_country = {
		limit = {
			has_strategic_land_adjacency = root
			any_political_movement = {
				is_revolutionary = yes
				OR = {
					is_political_movement_type = movement_socialist
					is_political_movement_type = movement_communist
					is_political_movement_type = movement_anarchist
				}
			}
		}
		add = 0.25
	}
	max = 1
}

# Country. Grows in quarter steps with war support while pressing a liberation wargoal against a neighbour. Feeds both Confrontation pivots.
state_and_revolution_liberation_war_bonus = {
	if = {
		limit = {
			pressing_liberation_wargoal_against_adjacent_country = yes
			any_scope_war = {
				has_war_support = { target = root value > 0 }
			}
		}
		add = 0.25
		if = {
			limit = {
				any_scope_war = {
					has_war_support = { target = root value >= 25 }
				}
			}
			add = 0.25
		}
		if = {
			limit = {
				any_scope_war = {
					has_war_support = { target = root value >= 50 }
				}
			}
			add = 0.25
		}
		if = {
			limit = {
				any_scope_war = {
					has_war_support = { target = root value >= 75 }
				}
			}
			add = 0.25
		}
	}
	max = 1
}

