# Country. Raw weight pulling the Economic bar towards Confrontation. Unbounded, and only the ratio against its Consolidation counterpart matters.
# Its factor breakdown is what the player sees in state_and_revolution_economic_confrontation_pivot_factors_tt.
state_and_revolution_economic_confrontation_pivot = {
	if = {
		limit = {
			has_journal_entry = je_state_and_revolution
		}
		if = {
			limit = {
				average_sol > average_expected_sol
			}
			add = {
				desc = "STATE_AND_REVOLUTION_SOL_SURPLUS_TT"
				value = state_and_revolution_sol_surplus
				min = 0
				max = 1
			}
		}
		if = {
			limit = {
				has_law_or_variant = law_type:law_factory_councils
			}
			add = {
				desc = "STATE_AND_REVOLUTION_HAS_FACTORY_COUNCILS_TT"
				value = 0.25
			}
		}
		if = {
			limit = {
				had_revolutionary_socialism_victory = yes
			}
			add = {
				desc = "STATE_AND_REVOLUTION_REVOLUTIONARY_VICTORY_TT"
				value = state_and_revolution_revolutionary_victory_bonus
			}
		}
		if = {
			limit = {
				state_and_revolution_neighbour_communist_revolution_bonus > 0
			}
			add = {
				desc = "STATE_AND_REVOLUTION_NEIGHBOUR_COMMUNIST_REVOLUTION_TT"
				value = state_and_revolution_neighbour_communist_revolution_bonus
			}
		}
		if = {
			limit = {
				state_and_revolution_liberation_war_bonus > 0
			}
			add = {
				desc = "STATE_AND_REVOLUTION_LIBERATION_WAR_TT"
				value = state_and_revolution_liberation_war_bonus
			}
		}
		if = {
			limit = {
				revolutionary_bloc_gdp_fraction > 0
			}
			add = {
				desc = "STATE_AND_REVOLUTION_REVOLUTIONARY_BLOC_GDP_TT"
				value = revolutionary_bloc_gdp_fraction
				multiply = 2
			}
		}
	}
	else = {
		value = 0
	}
}

# Country. Raw weight pulling the Economic bar towards Consolidation. Paired with the value above.
state_and_revolution_economic_consolidation_pivot = {
	if = {
		limit = {
			has_journal_entry = je_state_and_revolution
		}
		if = {
			limit = {
				has_variable = state_and_revolution_lower_strata_below_expected_sol_var
			}
			add = {
				desc = "STATE_AND_REVOLUTION_LOWER_STRATA_BELOW_EXPECTED_SOL_TT"
				value = var:state_and_revolution_lower_strata_below_expected_sol_var
				min = 0
				max = 1
			}
		}
		if = {
			limit = {
				any_scope_state = {
					has_famine = yes
				}
			}
			add = {
				desc = "STATE_AND_REVOLUTION_FAMINES_TT"
				value = state_and_revolution_famine_states
				multiply = 0.25
				min = 0
				max = 1
			}
		}
		add = {
			desc = "STATE_AND_REVOLUTION_PEASANTS_TT"
			value = state_and_revolution_peasant_fraction
			min = 0
			max = 1
		}
		if = {
			limit = {
				gdp_per_capita_ranking > 20
			}
			add = {
				desc = "STATE_AND_REVOLUTION_POOR_GDP_PER_CAPITA_TT"
				value = state_and_revolution_poor_gdp_per_capita_bonus
				min = 0
				max = 1
			}
		}
	}
	else = {
		value = 0
	}
}

# Country. Raw weight pulling the Political bar towards Confrontation.
# Note it swaps which movement type it measures once a reformist socialism victory has happened.
state_and_revolution_political_confrontation_pivot = {
	if = {
		limit = {
			has_journal_entry = je_state_and_revolution
		}
