			}
		}
		add = 40
	}
	if = {
		limit = {
			c:PRU ?= {
				ai_russia_poland_is_unfriendly_neighbor = yes
			}
		}
		add = 20
	}
	if = {
		limit = {
			c:AUS ?= {
				ai_russia_poland_is_unfriendly_neighbor = yes
			}
		}
		add = 20
	}
	if = {
		limit = {
			any_country_in_europe = {
				NOR = {
					c:GER ?= this
					c:PRU ?= this
					c:AUS ?= this
					c:POL ?= this
					this = root
				}
				country_rank >= rank_value:major_power
				OR = {
					is_in_geographic_region = geographic_region_central_europe
					is_in_geographic_region = geographic_region_eastern_europe
				}
				ai_russia_poland_is_unfriendly_neighbor = yes
			}
		}
		add = 10
	}
	if = {
		limit = {
			any_country_in_europe = {
				is_at_war = yes
				OR = {
					c:TUR ?= this
