inputs.common/script_values/static_treaty_accep:
#root = evaluating country
#scope:other_country = other country
#scope:treaty_options = treaty options
static_treaty_acceptance = {
	value = 0

	# We are doing this to be able to reuse loc across treaties and diplomatic actions
	root = {
		save_temporary_scope_as = target
	}
	scope:other_country = {
		save_temporary_scope_as = actor
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_BASE"
		value = -10
	}

	if = {
		limit = {
			exists = scope:bad_faith_factor
		}

		subtract = {
			value = 10
			add = {
				value = scope:bad_faith_factor
				multiply = 2
			}
			if = {
				limit = {
					has_variable = shimonoseki_gp
					c:JAP ?= scope:actor
				}
				add = 1000 # GPs will not regard the Shimonoseki Strait Indemnity as just a free gift
			}
			desc = "DIPLOMATIC_ACCEPTANCE_DEAL_IS_WORSE"
		}
	}

	subtract = {
		desc = "DIPLOMATIC_ACCEPTANCE_ONE_TIME_ARTICLES"

		if = {
			limit = {
				exists = scope:has_one_time_articles
			}
			value = 1000
		}
	}

	add = {
		desc = "DIPLOMATIC_REPUTATION_REASON"
		value = "scope:other_country.modifier:country_diplomatic_reputation_add"
		if = {
			limit = {
				root = {
					NOT = {
						has_law_or_variant = law_type:law_council_republic
					}
				}
				scope:other_country = {
					has_law_or_variant = law_type:law_council_republic
				}
			}
			subtract = {
				value = "scope:other_country.modifier:country_other_country_socialist_government_hostility_impact_add"
				multiply = {
					value = 1
					add = "scope:other_country.modifier:country_other_country_socialist_government_hostility_impact_mult"
				}
			}
			subtract = {
				value = "scope:other_country.modifier:country_other_country_socialist_government_hostility_impact_add"
				multiply = {
					value = 1
					add = "scope:other_country.modifier:country_other_country_socialist_government_hostility_impact_mult"
				}
			}
		}
	}

	subtract = {
		desc = "DIPLOMATIC_ACCEPTANCE_BINDING_PERIOD"

		if = {
			limit = {
				exists = scope:treaty_options.binding_period
				scope:treaty_options.binding_period >= 18250
			}
			add = 25

			add = {
				value = scope:treaty_options.binding_period
				min = 365
				divide = 365
				max = 150
			}
		}
	}

	subtract = {
		desc = "DIPLOMATIC_ACCEPTANCE_NOT_RECOGNIZED_BY_SPAIN_ACTOR"
		# Treaty Diplomacy will be impossible between Spain and her former colonies before she recognizes them

		if = {
			limit = {
				scope:other_country = {
					has_modifier = modifier_not_recognized_by_spain
				}
				OR = {
					c:SPA ?= this
					c:SPC ?= this
					was_formed_from = SPA
				}
				NOT = {
					scope:treaty_options ?= {
						any_scope_article_option = {
							has_type = recognize_independence
						}
					}
				}
			}
			value = 1000
		}
	}

	subtract = {
		desc = "DIPLOMATIC_ACCEPTANCE_NOT_RECOGNIZED_BY_SPAIN_TARGET"
		# Treaty Diplomacy will be impossible between Spain and her former colonies before she recognizes them

		if = {
			limit = {
				scope:other_country = {
					OR = {
						c:SPA ?= this
						c:SPC ?= this
						was_formed_from = SPA
					}
				}
				has_modifier = modifier_not_recognized_by_spain
				NOT = {
					scope:treaty_options ?= {
						any_scope_article_option = {
							has_type = recognize_independence
						}
					}
				}
			}
			value = 1000
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
		if = {
			limit = {
				OR = {
					has_attitude = {
						who = scope:other_country
						attitude = genial
					}
					has_attitude = {
						who = scope:other_country
						attitude = conciliatory
					}
					has_attitude = {
						who = scope:other_country
						attitude = loyal
					}
				}
			}
			value = 20
		}
		if = {
			limit = {
				OR = {
					has_attitude = {
						who = scope:other_country
						attitude = cooperative
					}
					has_attitude = {
						who = scope:other_country
						attitude = protective
					}
				}
			}
			value = 10
		}
		if = {
			limit = {
				has_attitude = {
					who = scope:other_country
					attitude = cautious
				}
			}
			value = -10
		}
		if = {
			limit = {
				OR = {
					has_attitude = {
						who = scope:other_country
						attitude = antagonistic
					}
					has_attitude = {
						who = scope:other_country
						attitude = domineering
					}
					has_attitude = {
						who = scope:other_country
						attitude = belligerent
					}
					has_attitude = {
						who = scope:other_country
						attitude = rebellious
					}
				}
			}
			value = -50
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_OVERLORD_ATTITUDE"
		if = {
			limit = {
				is_subject = yes
				NOT = { scope:other_country = top_overlord }
				NOR = {
					has_attitude = {
						who = top_overlord
						attitude = rebellious
					}
					has_attitude = {
						who = top_overlord
						attitude = defiant
					}
					has_attitude = {
						who = top_overlord
						attitude = antagonistic
					}
					has_attitude = {
						who = top_overlord
						attitude = belligerent
					}
					has_attitude = {
						who = top_overlord
						attitude = domineering
					}
				}
				top_overlord = {
					OR = {
						has_attitude = {
							who = scope:other_country
							attitude = antagonistic
						}
						has_attitude = {
							who = scope:other_country
							attitude = domineering
						}
						has_attitude = {
							who = scope:other_country
							attitude = belligerent
						}
						any_rival_country = {
							this = scope:other_country
						}
					}
				}
			}
			value = -25
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_RELATIONS"
		if = {
			limit = {
				"relations(scope:other_country)" >= relations_threshold:amicable
				"relations(scope:other_country)" < relations_threshold:friendly
			}
			value = 5
		}
		if = {
			limit = {
				"relations(scope:other_country)" >= relations_threshold:friendly
			}
			value = 10
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_INFAMY"
		if = {
			limit = {
				"scope:other_country.infamy" >= infamy_threshold:infamous
				"scope:other_country.infamy" < infamy_threshold:notorious
			}
			value = -10
		}
		if = {
			limit = {
				"scope:other_country.infamy" >= infamy_threshold:notorious
				"scope:other_country.infamy" < infamy_threshold:pariah
			}
			value = -25
		}
		if = {
			limit = {
				"scope:other_country.infamy" >= infamy_threshold:pariah
			}
			value = -50
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_RANK"

		if = {
			limit = { scope:other_country = { country_rank > root.country_rank } }
			value = 10
		}

		if = {
			limit = { scope:other_country = { country_rank < root.country_rank } }
			value = -10
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH"

		if = {
			limit = {
				NOT = { exists = scope:is_treaty_active }
				scope:other_country.army_power_projection > root.army_power_projection
			}
			value = {
				add = "scope:other_country.ai_army_comparison(root)"
				max = 20
				min = -10
			}

			if = {
				limit = {
					NOT = { has_strategic_land_adjacency = scope:other_country }
				}
				max = 10
			}
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_NAVY_STRENGTH"

		if = {
			limit = {
				NOT = { exists = scope:is_treaty_active }
				scope:other_country.naval_power_projection > root.naval_power_projection
			}
			value = {
				add = "scope:other_country.ai_navy_comparison(root)"
				max = 25
				min = -15
			}

			if = {
				limit = {
					NOT = { has_strategic_land_adjacency = scope:other_country }
				}
				min = -100
			}
		}
	}

	if = {
		limit = {
			NOT = { exists = scope:is_treaty_active }
			NOT = { exists = scope:is_renegotiation }
			"ai_treaty_fairness(scope:other_country)" < 0
		}
		add = {
			desc = "DIPLOMATIC_ACCEPTANCE_TREATY_FAIRNESS"
			value = "ai_treaty_fairness(scope:other_country)"
			divide = 2
			max = -1
			min = -50
		}
	}

	if = {
		limit = {
			"root.ai_ideological_opinion(scope:other_country)" > 0
		}
		add = {
			desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION"
			value = "root.ai_ideological_opinion(scope:other_country)"
			multiply = 0.25
			max = 10
		}
	}
	else_if = {
		limit = {
			"root.ai_ideological_opinion(scope:other_country)" < 0
		}
		add = {
			desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION_NEGATIVE"
			value = "root.ai_ideological_opinion(scope:other_country)"
			multiply = 0.5
			min = -25
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_PRINCIPLE_SACRED_CIVICS"

		if = {
			limit = {
				AND = {
					scope:other_country.power_bloc ?= {
						OR = {
							has_principle = principle:principle_sacred_civics_1
							has_principle = principle:principle_sacred_civics_2
							has_principle = principle:principle_sacred_civics_3
						}
					}
					scope:other_country.religion = root.religion
				}
			}
			value = 10
		}
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_SOURCE_PRO_LOBBY_CLOUT"
		value = "root.lobby_foreign_pro_clout(scope:other_country)"
		multiply = 50
		max = 15
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_SOURCE_ANTI_LOBBY_CLOUT"
		value = "root.lobby_foreign_anti_clout(scope:other_country)"
		multiply = -50
		min = -15
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_TARGET_PRO_LOBBY_CLOUT"
		value = "scope:other_country.lobby_foreign_pro_clout(root)"
		multiply = 100
		max = 15
	}

	add = {
		desc = "DIPLOMATIC_ACCEPTANCE_TARGET_ANTI_LOBBY_CLOUT"
		value = "scope:other_country.lobby_foreign_anti_clout(root)"
		multiply = -100
		min = -15
	}

	if = {
		limit = {
			scope:other_country ?= { is_ai = no }
			scope:treaty_options ?= {
				is_exchanging_obligations = no
				any_scope_article_option = {
					is_giftable_to = root
					is_desired_by = root
				}
				NOT = {
					any_scope_article_option = {
						OR = {
							NOT = { is_giftable_to = root }
							NOT = { is_desired_by = root }
						}
					}
				}
			}
		}
		add = {
			desc = "DIPLOMATIC_ACCEPTANCE_GIFT"
			value = 1000
		}
	}
	else_if = {
		limit = {
			scope:treaty_options ?= {
				is_equal_exchange_for = root
				any_scope_article_option = {
					is_desired_by = root
				}
			}
		}
		add = {
			desc = "DIPLOMATIC_ACCEPTANCE_EQUAL_EXCHANGE"
			value = 30
		}
	}

	if = {
		limit = {
			NOT = { exists = scope:is_renegotiation }
			scope:treaty_options ?= {
				is_historical_treaty = yes
				remaining_binding_period > 0
			}
		}
		add = {
			desc = "TRIGGER_IS_HISTORICAL_TREATY_NONE"
			value = 1000
		}
	}
	else_if = {
		limit = {
			exists = scope:is_renegotiation
			exists = scope:bad_faith_factor
			scope:treaty_options.amended_treaty ?= {
				is_historical_treaty = yes
				remaining_binding_period > 0
			}
		}
		add = {
			desc = "TRIGGER_IS_HISTORICAL_TREATY_NONE"
			value = -1000
		}
	}
}

threaten_naval_hostilities_acceptance = {
	# Relative naval strength
	add = {
		value = "scope:other_country.ai_navy_comparison(root)"
		multiply = 5
		max = 25
		min = 5 # You have to have a stronger navy to use this at all
		desc = "DIPLOMATIC_ACCEPTANCE_NAVY_COMBAT_POWER"
	}

	# Vulnerability - how much do we rely on our coast & trade
	multiply = {
		desc = "DIPLOMATIC_ACCEPTANCE_NAVAL_VULNERABILITY"
		value = 0.1
		add = {
			value = naval_vulnerability
			multiply = 1.9
		}
	}

	# Have they followed through on previous threats?
	if = {
		limit = {
			"scope:other_country.naval_hostility_average_damage_dealt" >= 0
		}

		multiply = {
			desc = "DIPLOMATIC_ACCEPTANCE_NAVAL_HOSTILITIES_PAST_DAMAGE"
			value = "scope:other_country.naval_hostility_average_damage_dealt"
			divide = 65
			min = 0.1
			max = 1.5
		}
	}

	# Are they lower rank?
	if = {
		limit = { country_rank > scope:other_country.country_rank }
		desc = "DIPLOMATIC_ACCEPTANCE_NAVAL_HOSTILITIES_RANK"
		multiply = 0.25
	}
}

threaten_naval_hostilities_infamy = {
	value = 5

	if = {
		limit = {
			scope:other_country.country_rank = rank_value:great_power
		}

		multiply = 3.0
	}
	else_if = {
		limit = {
			scope:other_country.country_rank = rank_value:major_power
		}

		multiply = 2.5
	}
	else_if = {
		limit = {
			NOT = { scope:other_country = { is_country_type = unrecognized } }
		}

		multiply = 2.0
	}
	else_if = {
		limit = {
			scope:other_country.country_rank = rank_value:unrecognized_major_power
		}

		multiply = 1.5
	}
}

ai_threaten_naval_hostilities_chance = {
	value = 0

	if = {
		limit = {
			"ai_navy_comparison(scope:other_country)" >= 1.0 # Roughly 2x as strong navy required
			is_diplomatic_play_committed_participant = no
			infamy < infamy_threshold:notorious
			country_rank > scope:other_country.country_rank
			NOR = {
				has_attitude = {
					who = scope:other_country
					attitude = protective
				}
				has_attitude = {
					who = scope:other_country
					attitude = genial
				}
				has_attitude = {
					who = scope:other_country
					attitude = cooperative
				}
				has_attitude = {
					who = scope:other_country
					attitude = conciliatory
				}
			}
		}

		add = { # Base 5-25% based on relative navy strength
			value = "ai_navy_comparison(scope:other_country)"
			multiply = 0.05
			max = 0.25
		}

		divide = { # Lower chance the higher the infamy
			value = threaten_naval_hostilities_infamy
			divide = 10
			min = 1
		}

		if = { # Less likely unless we have a hostile attitude
			limit = {
				NOR = {
					has_attitude = {
						who = scope:other_country
						attitude = antagonistic
					}
					has_attitude = {
						who = scope:other_country
						attitude = domineering
					}
					has_attitude = {
						who = scope:other_country
						attitude = belligerent
					}
				}
			}
			multiply = 0.33
		}

		multiply = { # More likely when demanding relief from a strait controller that is hurting us
			value = scope:strait_grievance
			multiply = 0.05
			add = 1
			max = 3
		}
	}
}

