					culture = {
						has_discrimination_trait = language_anglophone
					}
					scope:exiling_country_scope ?= {
						has_technology_researched = empiricism
						any_primary_culture = {
							has_discrimination_trait = language_anglophone
						}
					}
				}
				modifier = {
					if = {
						limit = {
							scope:exiling_country_scope ?= {
								NOT = {
									has_law_or_variant = law_type:law_compulsory_primary_school
								}
							}
						}
						add = 10
					}
					if = {
						limit = {
							scope:exiling_country_scope ?= {
								NOT = {
									has_law_or_variant = law_type:law_public_schools
								}
							}
						}
						add = 10
					}
					if = {
						limit = {
							scope:exiling_country_scope ?= {
								NOT = {
									has_law_or_variant = law_type:law_womens_suffrage
								}
							}
						}
						add = 10
					}
					if = {
						limit = {
							scope:exiling_country_scope ?= {
								NOR = {
									has_law_or_variant = law_type:law_graduated_taxation
									has_law_or_variant = law_type:law_proportional_taxation
								}
							}
						}
						add = 10
					}
				}
				set_ideology = ideology:ideology_utilitarian_leader
			}
			1 = { # Fallback
				set_ideology = ideology:ideology_jingoist_leader
			}
		}
	}
