					NOT = {
						$CORE_TRIGGER$ = $CORE_VALUE$
					}
				}
				NOT = {
					exists = c:AWA
				}
			}
			create_country = {
				tag = AWA
				origin = root
				state = s:STATE_AWADH.region_state:BIC
				on_created = {
					activate_law = law_type:law_monarchy
					activate_law = law_type:law_oligarchy
				}
			}
		}
		else_if = {
			limit = {
				any_scope_state = {
					state_region = s:STATE_AWADH
					NOT = {
						$CORE_TRIGGER$ = $CORE_VALUE$
					}
				}
				exists = c:MUG
			}
			s:STATE_AWADH.region_state:BIC = {
				set_state_owner = c:MUG
			}
		}
		if = {
			limit = {
				any_scope_state = {
					state_region = s:STATE_CENTRAL_PROVINCES
					NOT = {
						$CORE_TRIGGER$ = $CORE_VALUE$
					}
				}
				c:NAG ?= {
					any_scope_state = {
						state_region = s:STATE_CENTRAL_PROVINCES
					}
				}
			}
			s:STATE_CENTRAL_PROVINCES.region_state:BIC = {
				set_state_owner = c:NAG
			}
		}
		if = {
			limit = {
				any_scope_state = {
					state_region = s:STATE_BOMBAY
					NOT = {
						$CORE_TRIGGER$ = $CORE_VALUE$
					}
				}
				c:SAT ?= {
					any_scope_state = {
						state_region = s:STATE_BOMBAY
					}
				}
			}
			s:STATE_BOMBAY.region_state:BIC = {
				set_state_owner = c:SAT
			}
		}
		else_if = {
			limit = {
				any_scope_state = {
					state_region = s:STATE_BOMBAY
					NOT = {
						$CORE_TRIGGER$ = $CORE_VALUE$
					}
				}
				c:KHP ?= {
					any_scope_state = {
						state_region = s:STATE_BOMBAY
					}
				}
			}
			s:STATE_BOMBAY.region_state:BIC = {
				set_state_owner = c:KHP
			}
		}
		while = {
			limit = {
				any_scope_state = {
					NOT = {
						$CORE_TRIGGER$ = $CORE_VALUE$
					}
					OR = {
						AND = {
							state_is_in_india_collapse_regions = no
							any_neighbouring_state = {
								NOT = {
									owner = ROOT
								}
							}
						}
						any_neighbouring_state = {
							owner = {
								NOT = {
									this = ROOT
								}
								country_can_take_india_collapse_states = yes
							}
						}
					}
				}
			}
			every_country = {
				limit = {
					NOT = {
						this = ROOT
					}
					OR = {
						AND = {
							country_can_take_india_collapse_states = yes
							any_scope_state = {
								any_neighbouring_state = {
									owner = ROOT
									NOT = {
										$CORE_TRIGGER$ = $CORE_VALUE$
									}
								}
							}
						}
						any_scope_state = {
							any_neighbouring_state = {
								owner = ROOT
								NOT = {
									$CORE_TRIGGER$ = $CORE_VALUE$
								}
								state_is_in_india_collapse_regions = no
							}
						}
					}
				}
				save_scope_as = prince_scope
				ROOT = {
					random_scope_state = {
						limit = {
							NOT = {
								$CORE_TRIGGER$ = $CORE_VALUE$
							}
							any_neighbouring_state = {
								scope:prince_scope ?= owner
							}
							OR = {
								state_is_in_india_collapse_regions = no
								scope:prince_scope ?= {
									country_can_take_india_collapse_states = yes
								}
							}
						}
						set_state_owner = scope:prince_scope
					}
				}
			}
			clear_saved_scope = prince_scope
		}
	}
}
