inputs.common/scripted_triggers/00_ip3_victoria:
enacting_more_permissive_labour_associations_law = {
	OR = {
		AND = {
			OR = {
				has_law_or_variant = law_type:law_guild_system
				has_law_or_variant = law_type:law_combination_acts
			}
			OR = {
				is_enacting_law = law_type:law_anti_strike_laws
				is_enacting_law = law_type:law_right_to_associate
			}
		}
		AND = {
			OR = {
				has_law_or_variant = law_type:law_anti_strike_laws
				has_law_or_variant = law_type:law_corporatized_unions
			}
			is_enacting_law = law_type:law_right_to_associate
		}
	}
}

enacting_less_permissive_labour_associations_law = {
	OR = {
		AND = {
			OR = {
				has_law_or_variant = law_type:law_right_to_associate
			}
			OR = {
				is_enacting_law = law_type:law_corporatized_unions
				is_enacting_law = law_type:law_combination_acts
				is_enacting_law = law_type:law_anti_strike_laws
			}
		}
		AND = {
			has_law_or_variant = law_type:law_anti_strike_laws
			OR = {
				is_enacting_law = law_type:law_combination_acts
				is_enacting_law = law_type:law_corporatized_unions
			}
		}
		AND = {
			has_law_or_variant = law_type:law_corporatized_unions
			is_enacting_law = law_type:law_combination_acts
		}
	}
}

red_summer_liberal_victory_trigger = {
	AND = {
		custom_tooltip = {
			text = red_summer_complete_tt
			scope:journal_entry = { "scripted_bar_progress(red_summer_progress_bar)" >= 100 }
		}
		any_interest_group_in_government = {
			OR = {
				has_ideology = ideology:ideology_liberal
				has_ideology = ideology:ideology_universalist
				leader = {
					OR = {
						has_liberal_ideology = yes
						has_progressive_ideology = yes
						has_socialist_ideology = yes
					}
				}
			}
		}
	}
}

red_summer_radical_victory_trigger = {
	AND = {
		OR = {
			has_law_or_variant = law_type:law_presidential_republic
			has_law_or_variant = law_type:law_parliamentary_republic
			has_law_or_variant = law_type:law_council_republic
		}
		in_election_campaign = no
		legitimacy > 50
		any_interest_group_in_government = {
			OR = {
				has_ideology = ideology:ideology_proletarian
				leader = {
					OR = {
						has_ideology = ideology:ideology_radical
						has_socialist_ideology = yes
					}
				}
			}
		}
		custom_tooltip = {
			text = no_monarchists_in_government_tt
			NOT = {
				any_interest_group_in_government = {
					law_enactment_stance = {
						law = law_type:law_monarchy
						value > neutral
					}
				}
			}
		}
	}
}

hungary_owns_croatia = {
	any_subject_or_below ?= {
		country_has_primary_culture = cu:hungarian
		any_scope_state = {
			OR = {
				state_region = s:STATE_DALMATIA
				state_region = s:STATE_CROATIA
				state_region = s:STATE_SLAVONIA
			}
		}
	}
}

is_abolishing_subjecthood = {
	has_law_or_variant = law_type:law_subjecthood
	OR = {
		is_enacting_law = law_type:law_ethnostate
		is_enacting_law = law_type:law_national_supremacy
		is_enacting_law = law_type:law_racial_segregation
		is_enacting_law = law_type:law_cultural_exclusion
		is_enacting_law = law_type:law_multicultural
	}
}

# These exist so we can calculate whether a valid path to victory exists for the Danubian Federation

je_danubian_federation_czech_button_visible = {
	exists = c:AUS
	c:AUS = ROOT
	OR = {
		any_scope_state = {
			state_region = {
				is_homeland = cu:czech
			}
		}
		any_subject_or_below = {
			OR = {
				#is_subject_type = subject_type_crown_land
				is_subject_type = subject_type_personal_union
			}
			any_scope_state = {
				state_region = {
					is_homeland = cu:czech
				}
			}
		}
	}
	NAND = {
		has_variable = danubian_federation_czech_button
		NOT = {
			any_in_list = {
				variable = aus_integrated_cultures
				cu:czech ?= this
			}
		}
	}
	NOT = {
		any_in_list = {
			variable = aus_disqualified_cultures
			cu:czech ?= this
		}
	}
}

je_danubian_federation_czech_button_possible = {
	custom_tooltip = {
		text = danubian_federation_button_cooldown_tt
		NOT = {
			has_variable = danubian_federation_button_cooldown
		}
	}
	custom_tooltip = {
		text = not_already_used_this_interaction_tt
		NOT = {
			has_variable = danubian_federation_czech_button
		}
	}
	OR = {
		country_average_culture_pop_acceptance = {
			culture = cu:czech
			value >= acceptance_status_3
		}
		AND = {
			has_law_or_variant = law_type:law_subjecthood
			any_subject_or_below = {
				country_has_primary_culture = cu:czech
			}
		}
	}
	radical_fraction = {
		culture = cu:czech
		value <= 0.10
	}
	cu:czech = {
		trigger_if = {
			limit = {
				ROOT = {
					any_scope_state = {
						state_region = {
							is_homeland = cu:czech
						}
					}
				}
			}
			custom_tooltip = {
				text = all_culture_states_integrated_tt
				NOT = {
					ROOT = {
						any_scope_state = {
							state_region = {
								is_homeland = cu:czech
							}
							is_incorporated = no
						}
					}
				}
			}
		}
		custom_tooltip = {
			text = no_active_secession_movement_tt
			culture_secession_progress = { target = ROOT value = 0 }
		}
		trigger_if = {
			limit = {
				ROOT = {
					any_subject_or_below = {
						country_has_primary_culture = cu:czech
					}
				}
			}
			custom_tooltip = {
				text = not_enemy_of_any_country_with_culture_tt
				NOT = {
					ROOT = {
						any_subject_or_below = {
							country_has_primary_culture = cu:czech
							is_diplomatic_play_enemy_of = ROOT
						}
					}
				}
			}
		}
		custom_tooltip = {
			text = already_integrated_tt
			ROOT = {
				NOT = {
					any_in_list = {
						variable = aus_integrated_cultures
						cu:czech ?= this
					}
				}
			}
		}
		custom_tooltip = {
			text = culture_disqualified_tt
			ROOT = {
				NOT = {
					any_in_list = {
						variable = aus_disqualified_cultures
						cu:czech ?= this
					}
				}
			}
		}
	}
}

