any_neighbouring_country_has_same_movement_type_as_root = { # Used when ROOT is a political movement, checks for any neighbouring country having a political movement of this type
	owner ?= {
		any_neighbouring_state = {
			owner = {
				prestige > ROOT.owner.prestige
				any_political_movement = {
					type = ROOT.type
				}
			}
		}
	}
}

ser_exists_contender_of_other_dynasty = {
	OR = {
		AND = {
			ruler = {
				var:dynasty_var ?= flag:house_obrenovic
			}
			any_scope_character = {
				var:dynasty_var ?= flag:house_karadordevic
			}
		}
		AND = {
			ruler = {
				var:dynasty_var ?= flag:house_karadordevic
			}
			any_scope_character = {
				var:dynasty_var ?= flag:house_obrenovic
			}
		}
	}
}

ser_character_is_of_current_ruling_dynasty = { # In character scope
	OR = {
		AND = {
			owner.ruler = {
				var:dynasty_var ?= flag:house_obrenovic
			}
			var:dynasty_var ?= flag:house_obrenovic
		}
		AND = {
			owner.ruler = {
				var:dynasty_var ?= flag:house_karadordevic
			}
			var:dynasty_var ?= flag:house_karadordevic
		}
	}
}

ser_character_is_of_rival_dynasty = { # In character scope
	OR = {
		AND = {
			owner.ruler = {
				var:dynasty_var ?= flag:house_obrenovic
			}
			var:dynasty_var ?= flag:house_karadordevic
		}
		AND = {
			owner.ruler = {
				var:dynasty_var ?= flag:house_karadordevic
			}
			var:dynasty_var ?= flag:house_obrenovic
		}
	}
}

country_can_have_cultural_minority_movement_of_culture = { # Fired from the on_national_awakening_started on_action, has all of its scopes
	NOT = {
		any_political_movement = {
			culture ?= scope:culture
		}
	}
	OR = {
		any_scope_state = {
			state_region = {
				is_homeland = scope:culture
			}
			culture_percent_state = {
				target = scope:culture
				value >= 0.2
			}
		}
		AND = {
			culture_percent_country = {
				target = scope:culture
				value >= 0.1
			}
			cultural_acceptance_base = { target = scope:culture value <= acceptance_status_2 }
		}
	}
}

country_is_in_german_confederation = {
	OR = {
