	kind = directed
	cost = 0

	icon = "gfx/interface/icons/diplomatic_treaties_articles_icons/transfer_state.dds"

	flags = {
		causes_state_transfer
		giftable
		exclude_from_make_this_work
		ai_consider_threaten_naval_hostilities
		is_one_time
	}

	usage_limit = once_per_side_with_same_inputs

	maintenance_paid_by = source_country

    required_inputs = {
		state
    }

	visible = {
		is_revolutionary = no
	}

	can_ratify = {
		scope:source_country = {
			num_states >= 2
		}

		custom_tooltip = {
            text = DUPLICATE_ARTICLE_SAME_INPUTS
            scope:treaty ?= {
                NOT = {
                    any_scope_article_option = {
                        count > 1
                        has_type = state_transfer
                        source_country = scope:source_country
                        input_state = root.input_state
                    }
                }
            }
        }

		custom_tooltip = {
            text = STATE_TRANSFER_NOT_OWNER
            scope:article ?= {
                input_state = {
                    owner = scope:source_country
                }
            }
        }
    }

	state_valid_trigger = {
		scope:input = {
			owner = root
			is_capital = no
			is_under_colonization = no
			OR = {
				scope:other_country = { is_adjacent_to_state = prev }
				AND = {
					is_coastal = yes
					scope:other_country = { has_port_country = yes }
				}
			}
		}
	}

	on_entry_into_force = {
		scope:article_options = {
			target_country = {
				save_scope_as = state_taker
			}
			source_country = {
				save_scope_as = state_giver
			}

			if = {
				limit = { exists = input_state }
				input_state = { set_state_owner = scope:state_taker }
			}

			scope:state_taker ?= {
				if = {
					limit = {
						has_variable = recently_traded_states_counter
					}
					change_variable = {
						name = recently_traded_states_counter
						add = 1
					}
				}
				else_if = {
					limit = {
						NOT = { has_variable = recently_traded_states_counter }
					}
					set_variable = {
						name = recently_traded_states_counter
						value = 1
					}
				}
			}


			scope:state_giver ?= {
				if = {
					limit = {
						has_variable = recently_traded_states_counter
					}
					if = {
						limit = {
							var:recently_traded_states_counter > 1
						}
						change_variable = {
							name = recently_traded_states_counter
							subtract = 1
						}
					}
					else = {
						remove_variable = recently_traded_states_counter
					}
				}
			}
		}
	}

	on_withdrawal = {}
	on_break = {
		scope:withdrawing_country = {
			change_relations = {
				country = scope:non_withdrawing_country
				value = {
					value = -50
					add = {
						value = -50
						multiply = {
							value = scope:treaty_options.remaining_binding_period
							min = 365
							divide = 365
						}
					}
					max = -50
					min = -100
				}
			}
			change_infamy = {
				value = {
					value = 25
					add = {
						value = 25
						multiply = {
							value = scope:treaty_options.remaining_binding_period
							min = 365
							divide = 365
							divide = 25
						}
					}
					min = 25
					max = 50
				}
			}
		}
	}

	ai = {

		treaty_categories = {
			expansion
		}

		evaluation_chance = {
			value = 0.1
		}

		article_ai_usage = {
            request
        }

		inherent_accept_score = {
			value = 0

			if = {
				limit = {
					exists = scope:article.input_state
					scope:source_country ?= this
					OR = {
						NOT = { exists = scope:is_treaty_active }
						exists = scope:is_renegotiation
					}
					scope:article.input_state.ai_state_value:root > 0
				}
				subtract = {
					desc = "DIPLOMATIC_ACCEPTANCE_TRADE_STATE_SOURCE"
					value = scope:article.input_state.ai_state_value:root
					min = 100

					if = {
						limit = {
							scope:article.input_state = {
								any_neighbouring_state = {
									owner = scope:source_country
									OR = {
										is_incorporated = yes
										ai_can_incorporate_state = yes
									}
								}
							}
						}
						min = 200
					}

					if = {
						limit = {
							scope:source_country.country_rank > scope:target_country.country_rank
						}
						multiply = {
							add = scope:source_country.country_rank
							subtract = scope:target_country.country_rank
							divide = 10
							add = 1
						}
					}
				}

				if = {
					limit = {
						scope:article.input_state = {
							any_scope_strait = {
								exists = this
							}
						}
					}
					subtract = {
						value = 500
						desc = "concept_strait_controller"
					}
				}

				if = {
					limit = {
						ai_ceding_state_would_isolate_states = {
							STATE = scope:article.input_state
							CEDER = scope:source_country
							RECEIVER = scope:target_country
						}
					}
					subtract = {
						value = 1000
						desc = "DIPLOMATIC_ACCEPTANCE_WOULD_ISOLATE_STATES"
					}
				}

				if = {
					limit = {
						exists = scope:target_country.var:recently_traded_states_counter
						scope:target_country.var:recently_traded_states_counter > 0
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_RECENTLY_TRADED_STATES"

						value = -50
						multiply = scope:target_country.var:recently_traded_states_counter
					}
				}
			}
			else_if = {
				limit = {
					exists = scope:article.input_state
					scope:target_country ?= this
					OR = {
						NOT = { exists = scope:is_treaty_active }
						exists = scope:is_renegotiation
					}
					scope:article.input_state.ai_state_value:root > 0
				}
				add = {
					value = scope:article.input_state.ai_state_value:root
					desc = "DIPLOMATIC_ACCEPTANCE_TRADE_STATE_TARGET"
				}

				if = {
					limit = {
						OR = {
							ai_is_regional_objective_state = {
								TYPE = aro:ai_regional_objective_acquire_states
								STATE = scope:article.input_state
							}
							ai_is_regional_objective_state = {
								TYPE = aro:ai_regional_objective_recover_claims
								STATE = scope:article.input_state
							}
						}
					}
					add = {
						desc = "DIPLOMATIC_ACCEPTANCE_REGIONAL_OBJECTIVE_ACQUIRE"
						value = 25
					}
				}
			}
			else_if = {
				limit = {
					OR = {
						NOT = { exists = scope:is_treaty_active }
						exists = scope:is_renegotiation
					}
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_TRADE_STATE_REJECT"
					value = -300
				}
			}
		}
	}
}

inputs.common/treaty_articles/07_foreign_invest:
foreign_investment_rights = {
	kind = directed
	cost = 25

	relations_progress_per_day = 0.5
	relations_improvement_max = 50

	max_target_involvement = 2000
