							has_type = foreign_investment_rights
							source_country = root.top_overlord
						}
					}
				}
			}
		}
		trigger_if = {
			limit = {
				exists = power_bloc
				exists = scope:other_country.power_bloc
				power_bloc = scope:other_country.power_bloc
				power_bloc ?= {
					has_principle = principle:principle_foreign_investment_3
				}
			}
			NOT = {
				country_rank < scope:other_country.country_rank
			}
		}
	}

	can_ratify = {
