	after = {
		revoke_temporary_event_immortality = { CHARACTER = scope:cremieux_decree_leader_scope }
	}

	option = {
		name = algeria_events.2.a
		default_option = yes
		every_scope_state = {
			limit = {
				OR = {
					state_region = s:STATE_ALGIERS
