	trigger = {
		# triggered by on_action - on_yearly_events
		any_scope_state = {
			is_homeland_of_country_cultures = ROOT
			any_scope_culture = {
				NOT = { is_primary_culture_of = ROOT }
				PREV = {
					state_average_culture_pop_acceptance = { culture = prev value < acceptance_status_5 }
				}
			}
			any_scope_culture = {
				is_primary_culture_of = ROOT
			}
			average_sol < 10
		}
	}

	immediate = {
		random_scope_state = {
			limit = {
				is_homeland_of_country_cultures = ROOT
				any_scope_culture = {
					NOT = { is_primary_culture_of = ROOT }
					PREV = {
						state_average_culture_pop_acceptance = { culture = prev value < acceptance_status_5 }
					}
				}
				any_scope_culture = {
					is_primary_culture_of = ROOT
				}
				average_sol < 10
			}
			save_scope_as = culture_state
			random_scope_culture = {
				limit = {
					NOT = { is_primary_culture_of = ROOT }
