# Plague spreads
plague.2 = {
	type = country_event
	placement = scope:plague_spread_target

	title = plague.2.t
	desc = plague.2.d
	flavor = plague.2.f

	event_image = {
		video = "unspecific_sick_in_hospital"
	}

