	icon = "gfx/interface/icons/event_icons/event_newspaper.dds"

	duration = 3

	trigger = {
		has_global_variable = spanish_flu
		OR = {
			AND = {
				NOT = {
					has_journal_entry = je_spanish_flu
				}
