			target = THIS
		}
	}
}

assemble_socialist_movement_country_list_effect = {
	clear_global_variable_list = socialist_movement_country_list
	every_country = {
		limit = {
			has_technology_researched = socialism
			OR = {
				any_political_movement = {
					is_political_movement_type = movement_socialist
				}
				any_active_party = {
					party_counts_as_socialist_party = yes
