	if = {
		limit = {
			has_ideology = ideology:ideology_traditionalist_minoritarian
			owner.religion ?= religion
		}
		set_ideology = ideology:ideology_traditionalist
	}
	else_if = {
		limit = {
			has_ideology = ideology:ideology_traditionalist
			NOT = {
				owner.religion ?= religion
			}
		}
		set_ideology = ideology:ideology_traditionalist_minoritarian
	}
}

character_rule_length_counter_effects = {
	if = {
		limit = {
			is_ruler_of_own_country = yes
			owner = {
				has_gov_regency = yes
			}
		}
		if = {
			limit = {
				has_variable = regency_years
			}
			change_variable = { name = regency_years add = 1 } # Keeps track of how long one has been Regent
		}
		else = {
			set_variable = { name = regency_years value = 0 } # In case all else fails
		}
	}
	if = { # Handles total years in power, not consecutive years. Mostly for Japan.
		limit = {
			is_ruler_of_own_country = yes
		}
		if = {
			limit = {
				has_variable = year_in_power
			}
			change_variable = { name = year_in_power add = 1 } # Keeps track of how long one has been Regent
		}
		else = {
			set_variable = { name = year_in_power value = 1 } # In case all else fails
		}
	}
}


### on_country_released_* (shared across independent / own_subject / overlord_subject) ###

on_country_released_common_effect = {
	scope:target = {
		set_variable = { name = newly_released_country days = 90 } # Used for the Trialist Manifesto
		forest_of_bayonets_involve_country_effect = yes
	}
	if = {
		limit = {
			scope:target ?= {
				OR = {
					country_has_primary_culture = cu:ashkenazi
					country_has_primary_culture = cu:sephardic
				}
			}
			NOT = {
				s:STATE_PALESTINE = {
					OR = {
						is_homeland = cu:ashkenazi
						is_homeland = cu:sephardic
					}
				}
			}
		}
		s:STATE_PALESTINE = {
			add_homeland = cu:sephardic
			add_homeland = cu:ashkenazi
		}
	}
	if = {
		limit = {
			has_journal_entry = je_springtime_of_the_peoples
			NOT = {
				is_involved_in_journal_entry = je_springtime_of_the_peoples
			}
		}
		je:je_springtime_of_the_peoples ?= {
			add_involved_country = ROOT
		}
	}
	if = {
		limit = {
			c:YUG ?= scope:target
		}
		scope:target = {
			remove_primary_culture = cu:bulgarian
		}
	}
	if = {
		limit = {
			c:NEN ?= scope:target
		}
		scope:target ?= {
			create_character = {
				ig_leader = yes
				interest_group = ig_rural_folk
				ideology = ideology_luddite
			}
		}
	}
}

country_launch_abolish_monarchy_effect = {
	set_variable = {
		name = abolishing_monarchy_var
		value = 0
	}
	add_journal_entry = { type = je_abolish_monarchy }
}

on_country_formed_culture_effects = {
	# Paraguay gains Guarani as a primary culture
	if = {
		limit = {
			c:PLT ?= THIS
			was_formed_from = PRG
			has_variable = patino_paraguay_var
		}
		add_primary_culture = cu:guarani
	}
	# Yugoslavia drops Bulgarian culture unless it was formed from Bulgaria
	if = {
		limit = {
			c:YUG ?= ROOT
			NOT = { was_formed_from = BUL }
		}
		remove_primary_culture = cu:bulgarian
	}
	# Afghanistan gains regional cultures based on its origin
	if = {
		limit = {
			c:AFG ?= ROOT
			has_journal_entry = je_unify_afghanistan
		}
		if = {
			limit = {
				was_formed_from = KUN
			}
			add_primary_culture = cu:uzbek
		}
		if = {
			limit = {
				was_formed_from = MAI
			}
			add_primary_culture = cu:uzbek
			add_primary_culture = cu:turkmen
		}
		if = {
			limit = {
				was_formed_from = KAF
			}
			add_primary_culture = cu:kho
		}
	}
	if = {
		limit = {
			c:IBE ?= this
			has_variable_list = spain_accepted_cultures
		}
		on_country_formed_iberia_accepted_cultures_effect = yes
	}
}

on_yearly_pulse_country_achievement_variable_effects = {
	if = {
		limit = {
			any_scope_building = {
				NOR = {
					is_building_group = bg_government
					is_building_group = bg_construction
					is_building_group = bg_military
					is_building_group = bg_urban_facilities
					is_building_group = bg_canals
					is_building_group = bg_monuments_hidden
					is_building_group = bg_service
				}
				level > 0
				private_ownership_fraction = 1
			}
			NOT = {
				has_variable = achievement_for_twelve_years_you_have_been_asking_timed
				has_variable = achievement_for_twelve_years_you_have_been_asking
			}
		}
		set_variable = {
			name = achievement_for_twelve_years_you_have_been_asking_timed
			years = 12
		}
		set_variable = {
			name = achievement_for_twelve_years_you_have_been_asking
		}
	}
	else_if = {
		limit = {
			any_scope_building = {
				NOR = {
					is_building_group = bg_government
					is_building_group = bg_construction
					is_building_group = bg_military
					is_building_group = bg_urban_facilities
					is_building_group = bg_canals
					is_building_group = bg_monuments_hidden
					is_building_group = bg_service
				}
				level > 0
				private_ownership_fraction < 1
			}
			OR = {
				has_variable = achievement_for_twelve_years_you_have_been_asking_timed
				has_variable = achievement_for_twelve_years_you_have_been_asking
			}
		}
		# RESET THE CLOCK

		remove_variable = achievement_for_twelve_years_you_have_been_asking
		remove_variable = achievement_for_twelve_years_you_have_been_asking_timed
	}

	if = {
		limit = {
			any_scope_building = {
				level > 0
				private_ownership_fraction = 0
			}
			NOT = {
				has_variable = achievement_cant_touch_this_timed
				has_variable = achievement_cant_touch_this
			}
		}
		set_variable = {
			name = achievement_cant_touch_this_timed
			years = 12
		}
		set_variable = {
			name = achievement_cant_touch_this
		}
	}
	else_if = {
		limit = {
			any_scope_building = {
				level > 0
				private_ownership_fraction > 0
				NOR = {
					is_building_group = bg_subsistence_ranching
					is_building_group = bg_subsistence_agriculture
					is_building_group = bg_gold_fields
				}
			}
			OR = {
				has_variable = achievement_cant_touch_this_timed
				has_variable = achievement_cant_touch_this
			}
		}
		# RESET THE CLOCK

		remove_variable = achievement_cant_touch_this
		remove_variable = achievement_cant_touch_this_timed
	}
}

on_monthly_pulse_reform_or_revolution_effect = {
	if = { # If the JE has not begun, calculate the percent of global GDP controlled by countries which meet its requirements
		limit = {
			NOT = {
				has_global_variable = reform_or_revolution_global_var
			}
			global_gdp != 0
		}
		set_global_variable = { name = reform_or_revolution_countries_percent value = 0 }
		change_global_variable = {
			name = reform_or_revolution_countries_percent
			add = reform_or_revolution_countries_gdp
		}
		change_global_variable = {
			name = reform_or_revolution_countries_percent
			divide = global_gdp
		}
	}
	if = {
		limit = {
			NOT = {
				has_global_variable = reform_or_revolution_global_var
			}
			reform_or_revolution_countries_gdp >= {
				value = global_gdp
				multiply = 0.25
			}
		}
		set_global_variable = reform_or_revolution_global_var
	}
}
